export const PLANNER_HTML = "<!doctype html>\n<html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>헌드레드 정산 플래너</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans+KR:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500&display=swap\">\n<style>\n/* Layout: 왼쪽에 입력 패널, 오른쪽에 결과 (좁은 화면에서는 위아래). 정산 장부 느낌의 차분한 청색 톤 */\n:root {\n  --bg: #F2F4F8; --surface: #FFFFFF; --ink: #131820; --muted: #566174; --line: #DCE1E9; --line-soft: #EBEEF3;\n  --accent: #2346E8; --accent-ink: #FFFFFF; --accent-soft: #E6EBFF;\n  --good: #11795A; --good-soft: #DDF3EA; --warn: #9A5B00; --warn-soft: #FFEFD0; --bad: #B8321F; --bad-soft: #FDE4DF;\n  --font: 'IBM Plex Sans KR', 'Apple SD Gothic Neo', 'Malgun Gothic', 'Noto Sans KR', sans-serif;\n  --mono: 'IBM Plex Mono', ui-monospace, 'SFMono-Regular', Menlo, monospace;\n}\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme=\"light\"]) {\n    --bg: #0E1219; --surface: #161C26; --ink: #E8ECF3; --muted: #9AA4B5; --line: #2A3342; --line-soft: #202836;\n    --accent: #8197FF; --accent-ink: #0E1219; --accent-soft: #212C55;\n    --good: #46D1A0; --good-soft: #14352B; --warn: #EDB04F; --warn-soft: #3A2D12; --bad: #FF8272; --bad-soft: #3E1D19;\n    color-scheme: dark;\n  }\n}\n:root[data-theme=\"dark\"] {\n  --bg: #0E1219; --surface: #161C26; --ink: #E8ECF3; --muted: #9AA4B5; --line: #2A3342; --line-soft: #202836;\n  --accent: #8197FF; --accent-ink: #0E1219; --accent-soft: #212C55;\n  --good: #46D1A0; --good-soft: #14352B; --warn: #EDB04F; --warn-soft: #3A2D12; --bad: #FF8272; --bad-soft: #3E1D19;\n  color-scheme: dark;\n}\n* { box-sizing: border-box; }\nbody { background: var(--bg); color: var(--ink); font-family: var(--font); font-size: 14px; line-height: 1.55;\n  padding-block: 20px 56px; padding-left: max(16px, env(safe-area-inset-left, 0px)); padding-right: max(16px, env(safe-area-inset-right, 0px)); }\n.wrap { max-width: 1200px; margin: 0 auto; }\nh1 { font-size: 22px; line-height: 1.25; margin: 0; font-weight: 700; letter-spacing: -0.01em; }\nh2 { font-size: 15px; margin: 0 0 4px; font-weight: 700; letter-spacing: -0.005em; text-wrap: balance; }\n.sub { color: var(--muted); margin: 4px 0 0; font-size: 13px; }\n.hint { color: var(--muted); font-size: 12px; margin: 2px 0 10px; }\n.num, .mono { font-family: var(--mono); font-variant-numeric: tabular-nums; }\ntd, th, input, select { font-variant-numeric: tabular-nums; }\n.top { display: flex; justify-content: space-between; align-items: flex-end; gap: 12px; flex-wrap: wrap; margin-bottom: 16px; }\n.savebox { font-size: 12px; color: var(--muted); display: flex; align-items: center; gap: 6px; }\n.dot { width: 8px; height: 8px; border-radius: 50%; background: var(--good); display: inline-block; }\n.dot.off { background: var(--warn); }\n\n.layout { display: grid; grid-template-columns: minmax(0, 1fr); gap: 16px; align-items: start; }\n@media (min-width: 1000px) { .layout { grid-template-columns: minmax(0, 340px) minmax(0, 1fr); } .panel-in { position: sticky; top: 12px; } }\n.results { display: grid; gap: 16px; min-width: 0; }\n.box { background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 16px; min-width: 0; }\n.box.flat { border: 0; background: transparent; padding: 0; }\n\n.fgrid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px 10px; }\n.fgrid .wide { grid-column: 1 / -1; }\nlabel.fld { display: grid; gap: 4px; font-size: 12px; color: var(--muted); min-width: 0; }\nlabel.fld > span.l { display: flex; justify-content: space-between; gap: 6px; }\nlabel.fld small { color: var(--muted); font-size: 11px; font-weight: 400; }\ninput[type=number], input[type=month], select {\n  width: 100%; min-width: 0; font: inherit; font-size: 14px; color: var(--ink); background: var(--bg);\n  border: 1px solid var(--line); border-radius: 7px; padding: 8px 9px; }\ninput:focus-visible, select:focus-visible, button:focus-visible, summary:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }\n.chips { display: flex; gap: 6px; }\n.chip { flex: 1; font: inherit; font-size: 13px; padding: 7px 8px; border-radius: 7px; border: 1px solid var(--line); background: var(--bg); color: var(--ink); cursor: pointer; }\n.chip[aria-pressed=true] { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); font-weight: 600; }\n.btn { font: inherit; font-size: 13px; font-weight: 600; padding: 9px 12px; border-radius: 7px; border: 1px solid var(--accent); background: var(--accent); color: var(--accent-ink); cursor: pointer; }\n.btn.ghost { background: transparent; color: var(--accent); }\n.btn.quiet { background: transparent; color: var(--muted); border-color: var(--line); font-weight: 500; }\n.btn.small { padding: 5px 9px; font-size: 12px; }\n.divider { border: 0; border-top: 1px solid var(--line-soft); margin: 14px 0; }\n.sec-title { font-size: 12px; color: var(--muted); font-weight: 600; margin: 14px 0 8px; letter-spacing: 0.02em; }\n\n/* 요약 */\n.hero { display: grid; gap: 14px; }\n.tiles { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }\n@media (max-width: 640px) { .tiles { grid-template-columns: minmax(0, 1fr); } }\n.tile { border: 1px solid var(--line); border-radius: 9px; padding: 12px 14px; min-width: 0; }\n.tile .k { font-size: 12px; color: var(--muted); }\n.tile .v { font-family: var(--mono); font-size: 26px; font-weight: 500; line-height: 1.2; margin: 2px 0; letter-spacing: -0.02em; }\n.tile .v small { font-size: 13px; color: var(--muted); font-family: var(--font); letter-spacing: 0; margin-left: 2px; }\n.tile .s { font-size: 12px; color: var(--muted); }\n.verdict { border-radius: 9px; padding: 12px 14px; font-size: 14px; line-height: 1.6; border: 1px solid transparent; }\n.verdict b { font-weight: 700; }\n.verdict.good { background: var(--good-soft); color: var(--good); border-color: color-mix(in srgb, var(--good) 35%, transparent); }\n.verdict.warn { background: var(--warn-soft); color: var(--warn); border-color: color-mix(in srgb, var(--warn) 35%, transparent); }\n.verdict.bad { background: var(--bad-soft); color: var(--bad); border-color: color-mix(in srgb, var(--bad) 35%, transparent); }\n.verdict .t { color: var(--ink); }\n.pill { display: inline-block; font-size: 11px; padding: 1px 7px; border-radius: 999px; font-weight: 600; white-space: nowrap; }\n.pill.good { background: var(--good-soft); color: var(--good); }\n.pill.warn { background: var(--warn-soft); color: var(--warn); }\n.pill.bad { background: var(--bad-soft); color: var(--bad); }\n.pill.mute { background: var(--line-soft); color: var(--muted); }\n\n.tbl-wrap { overflow-x: auto; max-width: 100%; }\ntable { border-collapse: collapse; width: 100%; font-size: 13px; }\nth, td { padding: 7px 10px; text-align: right; border-bottom: 1px solid var(--line-soft); white-space: nowrap; }\nth { font-weight: 600; color: var(--muted); font-size: 12px; background: var(--surface); }\nth:first-child, td:first-child { text-align: left; }\ntr.hl td { background: var(--accent-soft); }\n.tbl-scroll { max-height: 440px; overflow: auto; }\n.tbl-scroll th { position: sticky; top: 0; z-index: 1; border-bottom: 1px solid var(--line); }\ntd.left, th.left { text-align: left; }\ntd.wrap-ok { white-space: normal; min-width: 150px; }\n.bar { height: 8px; background: var(--line-soft); border-radius: 99px; overflow: hidden; }\n.bar > i { display: block; height: 100%; background: var(--accent); border-radius: 99px; }\n.row2 { display: flex; justify-content: space-between; gap: 10px; flex-wrap: wrap; align-items: baseline; }\n.mutetxt { color: var(--muted); font-size: 12px; }\n\nsvg.chart { width: 100%; height: auto; display: block; }\nsvg.chart text { font-family: var(--font); font-size: 11px; fill: var(--muted); }\nsvg.chart .grid { stroke: var(--line-soft); stroke-width: 1; }\nsvg.chart .axis { stroke: var(--line); stroke-width: 1; }\nsvg.chart .mk { stroke: var(--muted); stroke-width: 1; stroke-dasharray: 3 3; opacity: .7; }\nsvg.chart .ln-cur { stroke: var(--accent); stroke-width: 2.4; fill: none; }\nsvg.chart .ln-hold { stroke: var(--warn); stroke-width: 2.2; fill: none; }\nsvg.chart .ln-base { stroke: var(--muted); stroke-width: 1.4; fill: none; stroke-dasharray: 5 4; opacity: .8; }\nsvg.chart .buf { stroke: var(--bad); stroke-width: 1; stroke-dasharray: 2 3; }\n.legend { display: flex; gap: 14px; flex-wrap: wrap; font-size: 12px; color: var(--muted); margin: 4px 0 6px; }\n.legend i { display: inline-block; width: 18px; height: 0; border-top: 2.4px solid; vertical-align: middle; margin-right: 5px; }\n.legend i.cur { border-color: var(--accent); } .legend i.hold { border-color: var(--warn); } .legend i.base { border-color: var(--muted); border-top-style: dashed; border-top-width: 1.5px; }\n.charts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 14px; }\n@media (max-width: 760px) { .charts { grid-template-columns: minmax(0, 1fr); } }\n\ndetails.acc { border-top: 1px solid var(--line-soft); padding: 10px 0; }\ndetails.acc summary { cursor: pointer; font-weight: 600; font-size: 13px; list-style: none; display: flex; justify-content: space-between; }\ndetails.acc summary::after { content: '+'; color: var(--muted); font-family: var(--mono); }\ndetails.acc[open] summary::after { content: '−'; }\ndetails.acc .fgrid { margin-top: 10px; }\n.fgrid3 { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 10px; }\n.scen-grid { display: grid; grid-template-columns: 1.6fr repeat(3, 1fr); gap: 6px; align-items: center; font-size: 12px; margin-top: 10px; }\n.scen-grid > b { color: var(--muted); font-weight: 600; }\n.confirm { border: 1px solid var(--accent); border-radius: 9px; padding: 12px 14px; margin-top: 10px; background: var(--accent-soft); }\n.confirm .acts { display: flex; gap: 8px; margin-top: 10px; }\n.empty { color: var(--muted); font-size: 13px; padding: 10px 0; }\nfooter.note { color: var(--muted); font-size: 12px; margin-top: 18px; display: grid; gap: 4px; }\n\n.calc{font-size:13px;line-height:1.6;margin:8px 0 14px;padding:8px 10px;background:var(--surface-2,rgba(127,127,127,.08));border-radius:8px}\n#teamBox h3{font-size:14px;margin:14px 0 6px}\n</style>\n<link rel=\"stylesheet\" href=\"https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/variable/pretendardvariable-dynamic-subset.min.css\">\n<style>\n:root, :root[data-theme=\"light\"] {\n  --bg: transparent; --surface: #ffffff; --ink: #0b2140; --muted: #6b7686; --line: #e4e7ee; --line-soft: #eef0f5;\n  --accent: #0b2140; --accent-ink: #ffffff; --accent-soft: #f6f0e1;\n  --good: #11795a; --good-soft: #e3f4ec; --warn: #8a6d2b; --warn-soft: #fbf3df; --bad: #b8321f; --bad-soft: #fde7e3;\n  --gold: #b8995a;\n  --font: 'Pretendard Variable', Pretendard, 'Malgun Gothic', 'Noto Sans KR', sans-serif; --mono: var(--font);\n}\nhtml, body { background: transparent; }\nbody { font-family: var(--font); font-size: 15px; padding-block: 4px 40px; }\n.wrap { max-width: 1180px; }\nh1 { font-size: 26px; font-weight: 900; color: #0b2140; letter-spacing: -0.02em; }\nh2 { font-size: 19px; font-weight: 900; color: #0b2140; margin: 0 0 6px; }\nh3 { font-size: 15px; font-weight: 800; color: #0b2140; margin: 16px 0 8px; }\n.num, .mono, td, th, input, select { font-variant-numeric: tabular-nums; }\n.box { border-radius: 24px; border: 1px solid var(--line); box-shadow: 0 1px 2px rgba(11,33,64,.04); padding: 22px; }\n.hint { font-size: 13px; }\n.top { margin-bottom: 14px; }\n.sub { font-size: 14px; }\n.savebox { gap: 10px; font-size: 13px; }\n.savebtn { font: inherit; font-size: 14px; font-weight: 800; padding: 9px 18px; border-radius: 999px; border: 0; cursor: pointer; color: #fff; background: linear-gradient(90deg, #0b2140, #4a5a9a); }\n.savebtn:active { transform: translateY(1px); }\n\n/* 수정할 곳 */\n.edit { background: #fffaf0; border: 1.5px solid #ecd9a6; }\n.edit .tag { display: inline-block; background: var(--gold); color: #fff; font-size: 12px; font-weight: 800; padding: 3px 11px; border-radius: 999px; margin-bottom: 8px; }\n.egrid { display: grid; gap: 14px; grid-template-columns: repeat(2, minmax(0, 1fr)); }\n@media (max-width: 860px) { .egrid { grid-template-columns: minmax(0, 1fr); } }\n.egroup { background: #fff; border: 1px solid #efe3bf; border-radius: 18px; padding: 16px; }\n.egroup > h3 { margin: 0 0 10px; display: flex; justify-content: space-between; align-items: baseline; }\n.egroup > h3 small { font-size: 12px; font-weight: 500; color: var(--muted); }\n.egroup.wide { grid-column: 1 / -1; }\n.fgrid3 { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }\n@media (max-width: 560px) { .fgrid3 { grid-template-columns: repeat(2, minmax(0, 1fr)); } .fgrid { grid-template-columns: minmax(0, 1fr); } }\nlabel.fld { font-size: 13px; font-weight: 600; color: #47546a; }\nlabel.fld small { font-weight: 500; }\ninput[type=number], input[type=month], select {\n  background: #fff; border: 1.5px solid #e4e7ee; border-radius: 12px; padding: 10px 12px; font-size: 16px; font-weight: 700; color: #0b2140; }\ninput[type=number]:focus, input[type=month]:focus, select:focus { outline: none; border-color: var(--gold); }\ninput::placeholder { color: #b6bdc9; font-weight: 500; font-size: 13px; }\n.crmrow { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; font-size: 13px; color: var(--muted); margin-bottom: 10px; }\n.crmrow label { cursor: pointer; display: inline-flex; gap: 6px; align-items: center; font-weight: 600; color: #0b2140; }\n.calc { background: #f6f7fb; border-radius: 12px; font-size: 13px; padding: 10px 12px; margin: 10px 0 4px; }\n.hire-in { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px; }\n@media (max-width: 560px) { .hire-in { grid-template-columns: minmax(0, 1fr); } }\n\n/* 결과 */\n.resdiv { display: flex; align-items: center; gap: 10px; margin: 6px 4px; color: #0b2140; font-weight: 900; font-size: 15px; }\n.resdiv::before, .resdiv::after { content: ''; flex: 1; border-top: 2px dashed #d7dbe5; }\n.tiles { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }\n@media (max-width: 900px) { .tiles { grid-template-columns: repeat(2, minmax(0, 1fr)); } }\n.tile { border-radius: 20px; padding: 18px; background: #fff; border: 1px solid var(--line); }\n.tile:first-child { background: linear-gradient(135deg, #10203a, #0a1424); border-color: #0a1424; }\n.tile:first-child .k, .tile:first-child .s, .tile:first-child .v small { color: rgba(255,255,255,.65); }\n.tile:first-child .v { color: #E8D080; }\n.tile .k { font-size: 13px; font-weight: 700; }\n.tile .v { font-size: 32px; font-weight: 900; color: #0b2140; margin: 4px 0; letter-spacing: -0.02em; }\n.tile .s { font-size: 12.5px; }\n.verdict { border-radius: 18px; padding: 14px 18px; font-size: 15px; }\n.bar { height: 10px; } .bar > i { background: linear-gradient(90deg, #0b2140, #b8995a); }\ntable { font-size: 14px; }\nth { font-size: 12.5px; background: transparent; }\ntd, th { padding: 9px 12px; }\ntr.hl td { background: #f6f0e1; }\n.pill { font-size: 12px; padding: 2px 9px; }\n.btn { border-radius: 999px; padding: 10px 18px; background: linear-gradient(90deg, #0b2140, #4a5a9a); border: 0; font-size: 14px; }\n.btn.quiet { background: #fff; color: #47546a; border: 1.5px solid var(--line); }\n.chip { border-radius: 999px; padding: 8px 10px; }\n.chip[aria-pressed=true] { background: #0b2140; border-color: #0b2140; }\ndetails.acc { border-radius: 14px; }\ndetails.more > summary { cursor: pointer; font-weight: 800; font-size: 16px; color: #0b2140; list-style: none; display: flex; justify-content: space-between; }\ndetails.more > summary::after { content: '펼치기 ▾'; color: var(--muted); font-size: 12.5px; font-weight: 600; }\ndetails.more[open] > summary::after { content: '접기 ▴'; }\ndetails.more > :not(summary) { margin-top: 14px; }\n.confirm { border-radius: 14px; }\n.resbox { display: grid; gap: 16px; }\n.savemsg { font-weight: 700; color: #0b2140; }\n</style>\n<script>document.documentElement.setAttribute(\"data-theme\",\"light\")</script>\n</head><body>\n<div class=\"wrap\">\n  <header class=\"top\">\n    <div>\n      <h1>정산 플래너</h1>\n      <p class=\"sub\" id=\"sub\"></p>\n    </div>\n    <div class=\"savebox\"><span class=\"dot off\" id=\"saveDot\"></span><span class=\"savemsg\" id=\"saveTxt\">불러오는 중</span><button class=\"savebtn\" type=\"button\" id=\"btnSave\">저장</button></div>\n  </header>\n\n  <section class=\"box edit\" id=\"editBox\" aria-label=\"수정할 곳\">\n    <span class=\"tag\">수정할 곳</span>\n    <h2>여기만 고치면 아래 결과가 바로 바뀝니다</h2>\n    <p class=\"hint\">숫자를 고치면 자동으로 저장됩니다. 단위는 만원이고, 비워두면 계획값으로 계산합니다.</p>\n    <div class=\"egrid\">\n      <div class=\"egroup\">\n        <h3>이번 정산 <small>정산하는 달 기준</small></h3>\n        <div class=\"fgrid\">\n          <label class=\"fld wide\"><span class=\"l\">정산하는 달 <small>이 달 계약 기준</small></span><input type=\"month\" id=\"in_periodEnd\"></label>\n          <label class=\"fld\"><span class=\"l\">보유 현금 <small>20일 정산 후 금액</small></span><input type=\"number\" id=\"in_cash\" inputmode=\"decimal\" step=\"any\"></label>\n          <label class=\"fld\"><span class=\"l\">월 저축 목표</span><input type=\"number\" id=\"f_customSave\" inputmode=\"decimal\" step=\"any\"></label>\n          <label class=\"fld\"><span class=\"l\">이번 달 저축 <small>확정되면</small></span><input type=\"number\" id=\"in_actualSave\" inputmode=\"decimal\" step=\"any\" placeholder=\"비우면 계약 기준 추정\"></label>\n          <label class=\"fld\"><span class=\"l\">앞으로 유지할 월 저축</span><input type=\"number\" id=\"in_holdSave\" inputmode=\"decimal\" step=\"any\" placeholder=\"비우면 이번 달과 같게\"></label>\n          <label class=\"fld wide\"><span class=\"l\">목표</span>\n            <select id=\"in_goal\">\n              <option value=\"A\">기한까지 신용취약까지 완납 (재단만 남김)</option>\n              <option value=\"B\">기한까지 햇살론만 완납</option>\n              <option value=\"D\">기한까지 재단까지 전부 완납</option>\n              <option value=\"C\">월 저축액 목표만 맞추기</option>\n            </select></label>\n        </div>\n      </div>\n\n      <div class=\"egroup\">\n        <h3>대출 잔액 <small>20일 정산 후 실제 값</small></h3>\n        <div class=\"fgrid3\">\n          <label class=\"fld\"><span class=\"l\">햇살론</span><input type=\"number\" id=\"f_L2\" inputmode=\"decimal\" step=\"any\"></label>\n          <label class=\"fld\"><span class=\"l\">신용취약</span><input type=\"number\" id=\"f_L3\" inputmode=\"decimal\" step=\"any\"></label>\n          <label class=\"fld\"><span class=\"l\">재단</span><input type=\"number\" id=\"f_L1\" inputmode=\"decimal\" step=\"any\"></label>\n        </div>\n        <h3 style=\"margin-top:18px\">직원 입사월 <small>바꿔 보면 판단이 바뀝니다</small></h3>\n        <div class=\"hire-in\" id=\"hireInputs\"></div>\n      </div>\n\n      <div class=\"egroup wide\">\n        <h3>이번 달 팀 실적 <small>CRM에서 자동으로 채워집니다 · 고쳐도 됩니다</small></h3>\n        <div class=\"crmrow\"><label><input type=\"checkbox\" id=\"crmAuto\"> CRM 숫자 자동 반영</label><button class=\"btn quiet small\" type=\"button\" id=\"btnCrm\">지금 다시 불러오기</button><span id=\"crmStamp\"></span></div>\n        <div class=\"egrid\">\n          <div>\n            <h3 style=\"margin-top:0\">영업팀</h3>\n            <div class=\"fgrid3\">\n              <label class=\"fld\"><span class=\"l\">계약 개수 <small>지금까지</small></span><input type=\"number\" id=\"in_soFar\" inputmode=\"decimal\" step=\"any\" min=\"0\"></label>\n              <label class=\"fld\"><span class=\"l\">매출 <small>지금까지</small></span><input type=\"number\" id=\"in_salesRev\" inputmode=\"decimal\" step=\"any\" min=\"0\" placeholder=\"비우면 계산\"></label>\n              <label class=\"fld\"><span class=\"l\">월말 예상 개수</span><input type=\"number\" id=\"in_finalC\" inputmode=\"decimal\" step=\"any\" min=\"0\" placeholder=\"비우면 계획\"></label>\n            </div>\n            <div class=\"calc\" id=\"tm_sales\"></div>\n          </div>\n          <div>\n            <h3 style=\"margin-top:0\">관리팀</h3>\n            <div class=\"fgrid3\">\n              <label class=\"fld\"><span class=\"l\">수수료 매출 <small>지금까지</small></span><input type=\"number\" id=\"in_mgrSuccNow\" inputmode=\"decimal\" step=\"any\" min=\"0\" placeholder=\"비우면 계획\"></label>\n              <label class=\"fld\"><span class=\"l\">별도계약 매출 <small>지금까지</small></span><input type=\"number\" id=\"in_mgrOwnNow\" inputmode=\"decimal\" step=\"any\" min=\"0\"></label>\n              <label class=\"fld\"><span class=\"l\">별도계약 월말</span><input type=\"number\" id=\"in_mgrOwnEnd\" inputmode=\"decimal\" step=\"any\" min=\"0\" placeholder=\"비우면 지금과 같게\"></label>\n            </div>\n            <div class=\"calc\" id=\"tm_mgr\"></div>\n          </div>\n        </div>\n        <h3>발굴팀 <small class=\"mutetxt\" style=\"font-weight:500\">DB 개수 (160개 넘는 만큼 1개당 1만원)</small></h3>\n        <div id=\"scoutRows\" class=\"egrid\">\n          <div class=\"fgrid3\" id=\"scoutRow0\"><label class=\"fld\"><span class=\"l\">발굴 #1 <small>지금까지</small></span><input type=\"number\" id=\"db0\" inputmode=\"decimal\" step=\"any\" min=\"0\"></label><label class=\"fld\"><span class=\"l\">월말 예상</span><input type=\"number\" id=\"dbe0\" inputmode=\"decimal\" step=\"any\" min=\"0\" placeholder=\"비우면 지금과 같게\"></label></div>\n          <div class=\"fgrid3\" id=\"scoutRow1\"><label class=\"fld\"><span class=\"l\">발굴 #2 <small>지금까지</small></span><input type=\"number\" id=\"db1\" inputmode=\"decimal\" step=\"any\" min=\"0\"></label><label class=\"fld\"><span class=\"l\">월말 예상</span><input type=\"number\" id=\"dbe1\" inputmode=\"decimal\" step=\"any\" min=\"0\" placeholder=\"비우면 지금과 같게\"></label></div>\n          <div class=\"fgrid3\" id=\"scoutRow2\"><label class=\"fld\"><span class=\"l\">발굴 #3 <small>지금까지</small></span><input type=\"number\" id=\"db2\" inputmode=\"decimal\" step=\"any\" min=\"0\"></label><label class=\"fld\"><span class=\"l\">월말 예상</span><input type=\"number\" id=\"dbe2\" inputmode=\"decimal\" step=\"any\" min=\"0\" placeholder=\"비우면 지금과 같게\"></label></div>\n        </div>\n        <div class=\"calc\" id=\"tm_scout\"></div>\n      </div>\n    </div>\n    <hr class=\"divider\">\n    <div style=\"display:flex;gap:10px;align-items:center;flex-wrap:wrap\"><button class=\"btn\" type=\"button\" id=\"btnClose\">20일 정산 완료 기록</button><span class=\"mutetxt\">정산을 마친 날 한 번 누르면 기록만 남습니다. 달은 CRM 달이 바뀌는 1일에 자동으로 넘어갑니다</span></div>\n    <div id=\"closePanel\"></div>\n  </section>\n\n  <div class=\"resdiv\" style=\"margin-top:16px\">▼ 아래는 결과입니다 · 확인만 하세요 ▼</div>\n\n  <div class=\"resbox\">\n    <section class=\"box hero\" id=\"hero\" aria-live=\"polite\"></section>\n    <section class=\"box\" id=\"crmBox\"></section>\n    <section class=\"box\" id=\"setBox\"></section>\n    <section class=\"box\" id=\"hireBox\"></section>\n    <section class=\"box\" id=\"schedBox\"></section>\n    <section class=\"box\" id=\"chartBox\"></section>\n    <section class=\"box\" id=\"needBox\" style=\"display:none\"></section>\n    <section class=\"box\"><details class=\"more\"><summary>월별 계획 표</summary><div id=\"tblBox\"></div></details></section>\n    <section class=\"box\"><details class=\"more\"><summary>정산 기록</summary><div id=\"logBox\"></div></details></section>\n    <section class=\"box\"><details class=\"more\"><summary>상세 가정 (잘 안 바뀌는 숫자)</summary>\n      <div class=\"fld\" style=\"margin-bottom:6px\"><span class=\"l\">시나리오 <small id=\"scenHint\"></small></span>\n        <div class=\"chips\" role=\"group\" aria-label=\"시나리오\">\n          <button class=\"chip\" type=\"button\" data-scen=\"1\" aria-pressed=\"false\">보수</button>\n          <button class=\"chip\" type=\"button\" data-scen=\"2\" aria-pressed=\"true\">기본</button>\n          <button class=\"chip\" type=\"button\" data-scen=\"3\" aria-pressed=\"false\">낙관</button>\n        </div></div>\n      <div id=\"assump\"></div></details></section>\n  </div>\n  <footer class=\"note\" id=\"foot\"></footer>\n</div>\n\n<script>\n/* 정산 플래너 계산 엔진 (단위: 만원). 월 = year*12 + (month-1) 정수 */\nconst ENG = (function () {\n  function ym(s) { const a = String(s).split('-'); return (+a[0]) * 12 + (+a[1] - 1); }\n  function ymStr(i) { return Math.floor(i / 12) + '-' + String(i % 12 + 1).padStart(2, '0'); }\n  const N = 26;\n\n  const DEFAULTS = {\n    periodEnd: '2026-10', cash: 1900,\n    L2: 1533.3333, L3: 3000, L1: 2000,\n    hist2: 13, hist1: 14,\n    settledMonth: '', soFar: 0, salesRev: null, mgrSuccNow: null, mgrOwnNow: null, mgrOwnEnd: null, scoutDb: [0, 0, 0], scoutDbEnd: [null, null, null], mgrOwnPct: 0.4, scoutBonusDb: 160, scoutBonus: 1, finalC: null, actualSave: null, holdSave: null,\n    scen: 2, goal: 'A', goalMonth: '', customSave: 350,\n    sc: ['2026-10', '2026-12', '2026-12'], sa: ['2026-12', '2026-12'],\n    buffer: 500, fee: 50, feePc: 90, incentive: 0.3333, taxSales: 0.10,\n    scoutSalary: 210, mgrFixed: 200, mgrPct: 0.10, mgrCap: 1500,\n    capRep: 50, ramp1: 0.4, ramp2: 0.7, packs: 0, packCost: 100, jobAd: 120, supplies: 10, taxRes: 0.10,\n    cvr: [0.20, 0.25, 0.30], dbScout: [80, 120, 160], ret: [0.5, 0.7, 0.9],\n    rentNow: 105, depNow: 800, moveMonth: '2027-03', rentNew: 105, depNew: 800, moveCost: 100,\n    card: 300, home: 65,\n    L2rate: 0.06, L2sch: 33.3333, L3rate: 0.05, L1rate: 0.03, prStart: '2028-01', prMonths: 36,\n    payJaedan: 0, giftRepay: 0,\n    wedMonth: '2027-06', wedFund: 800, honey: 500, gift: 4000, hall: 3000, houseTarget: 3000, eunDep: 1000,\n    carOn: 0, carPrice: 5000, carSale: 1000, carMonth: '2027-01', carLoan: 2000, carRate: 0.06, carTerm: 60,\n    expDep: 2000, expSetup: 1500, expBuf: 1500\n  };\n\n  function sv(p, k) { return p[k][p.scen - 1]; }\n\n  /* o: {mode:'plan'|'hold', saveThis:number|null, finalC:number|null, holdSave:number, payJaedan:0|1, sc:[ym..], sa:[ym..]} */\n  function sim(p, o) {\n    o = o || {};\n    const P0 = ym(p.periodEnd);\n    const sc = o.sc || p.sc.map(ym), sa = o.sa || p.sa.map(ym);\n    const cvr = sv(p, 'cvr'), dbS = sv(p, 'dbScout'), ret = sv(p, 'ret');\n    const wed = ym(p.wedMonth), mv = ym(p.moveMonth), prS = ym(p.prStart), carM = ym(p.carMonth);\n    const payJ = o.payJaedan != null ? o.payJaedan : p.payJaedan;\n    const carPmt = (p.carOn && p.carLoan > 0) ? (p.carLoan * (p.carRate / 12)) / (1 - Math.pow(1 + p.carRate / 12, -p.carTerm)) : 0;\n    const wedNeed = Math.max(0, p.wedFund + p.honey + p.houseTarget - p.eunDep - (p.gift - p.hall));\n    const rows = [];\n    const cHist = [p.hist2, p.hist1];\n    let cash = p.cash, b2 = p.L2, b3 = p.L3, b1 = p.L1, carBal = 0, base3 = 0, base1 = 0;\n    for (let i = 0; i < N; i++) {\n      const m = P0 + i;\n      const act = s => { const k = m - s; return (k < 0 ? 0 : k === 0 ? p.ramp1 : k === 1 ? p.ramp2 : 1) * ret; };\n      const aS = [act(sa[0]), act(sa[1])], aD = [act(sc[0]), act(sc[1]), act(sc[2])];\n      const hcSales = 1 + (m >= sa[0] ? 1 : 0) + (m >= sa[1] ? 1 : 0);\n      const hcScout = (m >= sc[0] ? 1 : 0) + (m >= sc[1] ? 1 : 0) + (m >= sc[2] ? 1 : 0);\n      const supply = (aD[0] + aD[1] + aD[2]) * dbS + p.packs * 10;\n      const cap = (1 + aS[0] + aS[1]) * p.capRep;\n      const used = Math.min(supply, cap);\n      const contractsModel = used * cvr;\n      let contracts = contractsModel;\n      if (i === 0) {\n        if (o.finalC != null) contracts = o.finalC;\n        else contracts = Math.max(contractsModel, p.soFar || 0);\n      }\n      cHist.push(contracts);\n      const succ = cHist[i] * p.feePc;               // 계약 2개월 뒤 입금\n      const revFee = contracts * p.fee, rev = revFee + succ;\n      const mgrN = Math.max(1, Math.ceil(succ / p.mgrCap - 1e-9));\n      const cInc = revFee * (p.incentive + p.taxSales), cScout = hcScout * p.scoutSalary;\n      const cMgr = mgrN * p.mgrFixed + p.mgrPct * succ, cDb = p.packs * p.packCost;\n      const cAd = p.jobAd, cRent = m < mv ? p.rentNow : p.rentNew, cSup = p.supplies;\n      const cTotal = cInc + cScout + cMgr + cDb + cAd + cRent + cSup;\n      const op = rev - cTotal, tax = Math.max(0, op) * p.taxRes, opNet = op - tax;\n      const personal = p.card + p.home;\n      const int2 = b2 * p.L2rate / 12, sch2 = Math.min(b2, p.L2sch);\n      const int3 = b3 * p.L3rate / 12;\n      if (m === prS) { base3 = b3; base1 = b1; }\n      const req3 = m >= prS ? Math.min(b3, base3 / p.prMonths) : 0;\n      const req1 = m >= prS ? Math.min(b1, base1 / p.prMonths) : 0;\n      const int1 = ((m % 12) + 1) % 3 === 0 ? b1 * p.L1rate / 4 : 0;\n      const intTotal = int1 + int2 + int3, prin = sch2 + req3 + req1;\n      const carP = (p.carOn && m > carM) ? carPmt : 0;\n      if (!p.carOn || m < carM) carBal = 0; else if (m === carM) carBal = p.carLoan; else carBal = carBal * (1 + p.carRate / 12) - carPmt;\n      const modelFree = opNet - personal - intTotal - prin - carP;\n      let free;\n      if (i === 0) free = (o.saveThis != null) ? o.saveThis : modelFree;\n      else if (o.mode === 'hold') free = o.holdSave - req3 - req1 - carP;\n      else free = modelFree;\n      const eMove = m === mv ? p.depNow - p.depNew - p.moveCost : 0;\n      const eWed = m === wed ? -(p.wedFund + p.honey) + (p.gift - p.hall) - (p.houseTarget - p.eunDep) : 0;\n      const eCar = (p.carOn && m === carM) ? -(p.carPrice - p.carSale) + p.carLoan : 0;\n      const post = i === 0 && !!p.settledMonth && p.settledMonth === p.periodEnd;   // 정산 후 금액이면 이번 달 흐름을 다시 더하지 않음\n      const pre = post ? cash + eMove + eWed + eCar : cash + free + eMove + eWed + eCar;\n      const reserve = (m < wed ? wedNeed : 0) + (m < mv ? p.moveCost : 0) + ((p.carOn && m < carM) ? p.carPrice - p.carSale - p.carLoan : 0);\n      const budget = Math.max(Math.max(0, pre - p.buffer - reserve), m === wed ? p.giftRepay : 0);\n      const pp2 = post ? 0 : Math.min(budget, b2 - sch2);\n      const pp3 = post ? 0 : Math.min(budget - pp2, b3 - req3);\n      const pp1 = (payJ && !post) ? Math.min(budget - pp2 - pp3, b1 - req1) : 0;\n      const e2 = post ? b2 : b2 - sch2 - pp2, e3 = post ? b3 : b3 - req3 - pp3, e1 = post ? b1 : b1 - req1 - pp1;\n      cash = pre - (pp1 + pp2 + pp3);\n      const debtCore = e1 + e2 + e3;\n      rows.push({ i, m, label: ymStr(m), hcSales, hcScout, mgrN, supply, cap, used, gap: supply - cap, contractsModel, contracts,\n        revFee, succ, rev, cInc, cScout, cMgr, cDb, cAd, cRent, cSup, cTotal, op, tax, opNet, personal, int1, int2, int3, intTotal,\n        sch2, req3, req1, prin, carP, modelFree, free, eMove, eWed, eCar, pre, reserve, budget, pp1, pp2, pp3, e1, e2, e3,\n        carBal, debtCore, debtTotal: debtCore + carBal, cash });\n      b2 = e2; b3 = e3; b1 = e1;\n    }\n    return { rows, wedNeed };\n  }\n\n  function expFund(p) { return (p.expDep - p.depNew) + p.expSetup + p.expBuf; }\n\n  function milestones(res, p) {\n    const rows = res.rows, P0 = rows[0].m;\n    const first = fn => { for (const r of rows) if (fn(r)) return r.i; return -1; };\n    const wedIdx = ym(p.wedMonth) - P0, mv = ym(p.moveMonth), ef = expFund(p);\n    const o = {};\n    o.m2 = first(r => r.e2 <= 0.01);\n    o.m3 = first(r => r.e3 <= 0.01);\n    o.mExp = first(r => r.m >= mv && r.e2 <= 0.01 && r.e3 <= 0.01 && r.cash - p.buffer >= ef);\n    o.wedIdx = wedIdx;\n    if (wedIdx >= 0 && wedIdx < N) {\n      o.debtWed = rows[wedIdx].debtCore; o.cashWed = rows[wedIdx].cash;\n      o.cashBeforeWed = wedIdx > 0 ? rows[wedIdx - 1].cash : p.cash;\n    }\n    let minC = Infinity, minI = 0;\n    rows.forEach(r => { if (r.cash < minC) { minC = r.cash; minI = r.i; } });\n    o.minCash = minC; o.minIdx = minI;\n    o.firstShort = first(r => r.cash < p.buffer - 1);\n    o.firstNeg = first(r => r.cash < -0.5);\n    o.debtEnd = rows[N - 1].debtTotal;\n    return o;\n  }\n\n  /* 목표 달성에 필요한 매달 저축(균등) */\n  function goalIdx(p) { return ym(p.goalMonth || p.wedMonth) - ym(p.periodEnd); }\n  function meets(p, dIdx, S, fixed0) {\n    const goal = p.goal;\n    const r = sim(p, { mode: 'hold', saveThis: fixed0 != null ? fixed0 : S, holdSave: S, payJaedan: goal === 'D' ? 1 : p.payJaedan });\n    const row = r.rows[dIdx]; if (!row) return false;\n    const ok = row.e2 <= 0.01 && (goal === 'B' || row.e3 <= 0.01) && (goal !== 'D' || row.e1 <= 0.01);\n    let minc = Infinity; for (let i = 0; i <= dIdx; i++) minc = Math.min(minc, r.rows[i].cash);\n    return ok && minc >= p.buffer - 1;\n  }\n  function solveS(p, fixed0) {\n    if (p.goal === 'C') return p.customSave;\n    const dIdx = goalIdx(p);\n    if (dIdx < 0 || dIdx >= N) return null;\n    if (!meets(p, dIdx, 8000, fixed0)) return null;\n    if (meets(p, dIdx, 0, fixed0)) return 0;\n    let lo = 0, hi = 8000;\n    for (let k = 0; k < 40; k++) { const mid = (lo + hi) / 2; if (meets(p, dIdx, mid, fixed0)) hi = mid; else lo = mid; }\n    return hi;\n  }\n\n  /* 이번 달: 목표 저축을 맞추려면 필요한 계약 건수 (row0 구조 기준) */\n  function needContracts(p, r0, targetSave) {\n    const netNeeded = targetSave + r0.personal + r0.intTotal + r0.prin + r0.carP;\n    const opNeeded = netNeeded > 0 ? netNeeded / (1 - p.taxRes) : netNeeded;\n    const other = r0.cScout + r0.cMgr + r0.cDb + r0.cAd + r0.cRent + r0.cSup;\n    const F = (opNeeded + other - r0.succ) / (1 - p.incentive - p.taxSales);\n    const c = Math.max(0, F / p.fee);\n    return { contracts: c, fee: c * p.fee, rev: c * p.fee + r0.succ };\n  }\n\n  /* 정상 상태 필요 인원 */\n  function staffing(p, plan) {\n    const ret = sv(p, 'ret'), dbS = sv(p, 'dbScout');\n    const nSales = 1 + p.sa.length;\n    const capEff = (1 + (nSales - 1) * ret) * p.capRep;\n    const scoutEff = dbS * ret;\n    const needScouts = Math.max(1, Math.ceil(capEff / scoutEff - 1e-9));\n    const last = plan.rows[N - 1];\n    const needMgr = Math.max(1, Math.ceil(last.succ / p.mgrCap - 1e-9));\n    return { nSales, nScoutPlan: p.sc.length, needScouts, needMgr, capEff, scoutEff };\n  }\n\n  function goalOk(p, res) {\n    const dIdx = goalIdx(p), row = res.rows[dIdx];\n    if (!row || p.goal === 'C') return null;\n    const ok = row.e2 <= 0.01 && (p.goal === 'B' || row.e3 <= 0.01) && (p.goal !== 'D' || row.e1 <= 0.01);\n    let minc = Infinity; for (let i = 0; i <= dIdx; i++) minc = Math.min(minc, res.rows[i].cash);\n    return ok && minc >= p.buffer - 1;\n  }\n\n  /* 직원 가장 빠른 안전 시작월 (현금이 비상금 아래로 안 내려가는 가장 빠른 달) */\n  function safeStart(p, kind, idx, baseO) {\n    const P0 = ym(p.periodEnd);\n    for (let k = 0; k <= 14; k++) {\n      const sc = (baseO.sc || p.sc.map(ym)).slice(), sa = (baseO.sa || p.sa.map(ym)).slice();\n      if (kind === 'sc') sc[idx] = P0 + k; else sa[idx] = P0 + k;\n      const r = sim(p, Object.assign({}, baseO, { sc, sa }));\n      let ok = true;\n      for (let i = 0; i < 18; i++) if (r.rows[i].cash < p.buffer - 1) { ok = false; break; }\n      if (ok) return P0 + k;\n    }\n    return null;\n  }\n\n  return { ym, ymStr, N, DEFAULTS, sv, sim, milestones, solveS, goalIdx, goalOk, needContracts, staffing, safeStart, expFund };\n})();\nif (typeof module !== 'undefined') module.exports = ENG;\n\n</script>\n<script>\n(function () {\n  const E = ENG, KEY = 'hundred-planner-v1', N = E.N;\n  const clone = o => JSON.parse(JSON.stringify(o));\n  const $ = id => document.getElementById(id);\n  const nf = new Intl.NumberFormat('ko-KR', { maximumFractionDigits: 0 });\n  const nf1 = new Intl.NumberFormat('ko-KR', { maximumFractionDigits: 1, minimumFractionDigits: 1 });\n  const fmt = n => (n == null || isNaN(n)) ? '-' : (Math.round(n) < 0 ? '−' : '') + nf.format(Math.abs(Math.round(n)));\n  const f1 = n => (n == null || isNaN(n)) ? '-' : (n < -0.05 ? '−' : '') + nf1.format(Math.abs(n));\n  const kr = mi => Math.floor(mi / 12) + '년 ' + (mi % 12 + 1) + '월';\n  const esc = s => String(s).replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\n\n  let S = { v: 2, p: clone(E.DEFAULTS), log: [] };\n  let R = null;\n\n  /* ---------- 저장 ---------- */\n  const Store = {\n    ref: true, timer: null, saving: false, dirty: false,\n    async init() {\n      let remote = null, local = null;\n      try { const r = await fetch('/api/settings?key=planner', { cache: 'no-store' }); if (r.ok) { const j = await r.json(); remote = j.settings || null; } else this.ref = false; } catch (e) { this.ref = false; }\n      try { local = JSON.parse(localStorage.getItem(KEY)); } catch (e) { }\n      return remote || local;\n    },\n    save() {\n      try { localStorage.setItem(KEY, JSON.stringify(S)); } catch (e) { }\n      if (!this.ref) { status('저장됨', true); return; }\n      this.dirty = true; status('저장 중…', false);\n      clearTimeout(this.timer); this.timer = setTimeout(() => this.flush(), 500);\n    },\n    async flush() {\n      if (this.saving) { this.timer = setTimeout(() => this.flush(), 400); return; }\n      clearTimeout(this.timer); this.saving = true;\n      try {\n        const r = await fetch('/api/settings', { method: 'POST', headers: { 'Content-Type': 'application/json' }, keepalive: true, body: JSON.stringify(Object.assign({ _key: 'planner' }, clone(S))) });\n        if (!r.ok) throw new Error('save');\n        this.dirty = false; const d = new Date();\n        status('저장됨 ' + String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'), true);\n      } catch (e) { status('저장 실패 · 다시 눌러 주세요', false); }\n      this.saving = false;\n    }\n  };\n  window.addEventListener('pagehide', () => { if (Store.dirty) Store.flush(); });\n  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden' && Store.dirty) Store.flush(); });\n  function status(t, ok) { $('saveTxt').textContent = t; $('saveDot').className = 'dot' + (ok ? '' : ' off'); }\n\n\n  /* ---------- CRM 연동 ---------- */\n  let CRM = null, CRM_ERR = '';\n  const man1 = v => Math.round((v || 0) / 1000) / 10;\n  const mf = v => fmt(Math.round((v || 0) / 10000));\n  function renderCrm() {\n    const st = $('crmStamp'), box = $('crmBox'); if (!st || !box) return;\n    $('crmAuto').checked = S.p.crmAuto !== 0;\n    if (CRM_ERR) { st.textContent = 'CRM 숫자를 불러오지 못했습니다 (' + CRM_ERR + ') · 직접 적어도 됩니다'; box.innerHTML = ''; box.style.display = 'none'; return; }\n    if (!CRM) { st.textContent = '불러오는 중…'; return; }\n    const d = new Date(CRM.syncedAt);\n    st.textContent = CRM.month + ' 기준 · ' + String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0') + ' 불러옴' + (CRM.month === S.p.periodEnd ? '' : ' · 정산하는 달이 달라 자동 반영 안 함');\n    const sp = CRM.sales.people || [], nS = (CRM.staff.sales || []).length || 1;\n    let h = '<div class=\"row2\"><h2>직원별 현황 <small class=\"mutetxt\">CRM · ' + esc(CRM.month) + ' 지금까지</small></h2><span class=\"mutetxt\">영업 ' + (CRM.staff.sales || []).length + '명 · 관리 ' + (CRM.staff.ops || []).length + '명 · 발굴 ' + (CRM.staff.dig || []).length + '명</span></div>';\n    h += '<div class=\"tbl-wrap\"><table><thead><tr><th>영업팀</th><th>계약 개수</th><th>매출</th><th>예상 월급(올인센)</th><th>예상 월급(160+7%)</th></tr></thead><tbody>';\n    sp.forEach(p => { h += '<tr><td>' + esc(p.name) + '</td><td class=\"num\">' + f1(p.count) + '</td><td class=\"num\">' + mf(p.revenue) + '</td><td class=\"num\">' + mf(p.payAll) + '</td><td class=\"num\">' + mf(p.payBase7) + '</td></tr>'; });\n    h += '<tr class=\"hl\"><td><b>합계</b></td><td class=\"num\"><b>' + f1(CRM.sales.count) + '</b></td><td class=\"num\"><b>' + mf(CRM.sales.revenue) + '</b></td><td></td><td></td></tr></tbody></table></div>';\n    if (CRM.tax) h += '<div class=\"calc\"><b>세금 (홈택스 신고 기준 · ' + esc(CRM.tax.asOf) + ')</b> 파킹통장에 있어야 할 금액 <b>' + mf(CRM.tax.parking) + '만원</b> (종소세 ' + mf(CRM.tax.incomeTax) + ' + 부가세 ' + mf(CRM.tax.vat) + ') · 실제 있어야 할 금액 <b>' + mf(CRM.tax.actual) + '만원</b> <span class=\"mutetxt\">세금계산 탭에서 고칩니다</span></div>';\n    h += '<div class=\"calc\"><b>성장 좌표</b> · 영업 1명이 최근 3개월 평균 월 <b>' + f1(CRM.sales.avg3.count / nS) + '개 · ' + mf(CRM.sales.avg3.revenue / nS) + '만원</b>. 새 영업 직원이 자리 잡으면 한 달 매출이 이만큼 늘고, 발굴 직원 1명은 월 약 160개 DB를 만듭니다. 입사월을 바꿔 위에서 확인하세요.</div>';\n    box.style.display = ''; box.innerHTML = h;\n  }\n  async function syncCrm() {\n    try {\n      const r = await fetch('/api/planner/sync', { cache: 'no-store' });\n      if (!r.ok) throw new Error('HTTP ' + r.status);\n      CRM = await r.json(); CRM_ERR = '';\n      // 달이 바뀌면(1일) 자동으로 새 달로: 지난달 확정 개수를 기록에 남기고 이번 달 실적 칸을 비운다\n      if (CRM.month > S.p.periodEnd) {\n        const old = S.log.find(x => x.month === S.p.periodEnd);\n        if (old) old.contracts = CRM.sales.hist1;\n        Object.assign(S.p, { periodEnd: CRM.month, settledMonth: '', soFar: 0, finalC: null, actualSave: null, salesRev: null, mgrSuccNow: null, mgrOwnNow: null, mgrOwnEnd: null, scoutDb: [0, 0, 0], scoutDbEnd: [null, null, null] });\n        syncInputs(); update(); Store.save();\n      }\n      if (S.p.crmAuto !== 0 && CRM.month === S.p.periodEnd) {\n        S.p.soFar = CRM.sales.count; S.p.salesRev = man1(CRM.sales.revenue);\n        S.p.mgrSuccNow = man1(CRM.ops.feeRevenue); S.p.mgrOwnNow = man1(CRM.ops.ownContractRevenue);\n        S.p.hist1 = CRM.sales.hist1; S.p.hist2 = CRM.sales.hist2;\n        for (let k = 0; k < 3; k++) S.p.scoutDb[k] = (CRM.dig[k] && CRM.dig[k].db) || 0;\n        syncInputs(); update(); Store.save();\n      }\n    } catch (e) { CRM_ERR = e.message || String(e); }\n    renderCrm();\n  }\n  function wireCrm() {\n    $('btnCrm').onclick = syncCrm;\n    $('btnSave').onclick = () => Store.flush();\n    $('crmAuto').onchange = e => { S.p.crmAuto = e.target.checked ? 1 : 0; touch(); if (e.target.checked) syncCrm(); };\n  }\n  function postH() { try { parent.postMessage({ type: 'planner-h', h: document.documentElement.scrollHeight }, '*'); } catch (e) { } }\n  try { new ResizeObserver(postH).observe(document.body); } catch (e) { }\n  window.addEventListener('load', postH);\n\n  /* ---------- 입력 필드 정의 ---------- */\n  const FIELDS = [\n    ['지난 계약 (성공수수료 계산용)', [['hist2', '2개월 전 계약 건수 (이번 달 성공수수료)', 'num', '이번 달 성공수수료는 2개월 전 계약에서 나옵니다'], ['hist1', '1개월 전 계약 건수', 'num', '다음 달 성공수수료에 쓰입니다']]],\n    ['영업 · 매출', [['fee', '계약 1건당 착수금', 'num', ''], ['feePc', '계약 1건당 성공수수료', 'num', '관리팀 평소 매출 ÷ 월 계약 건수로 추정한 값. 실제 값으로 바꾸세요'],\n      ['incentive', '영업 인센티브율', 'pct', '착수금 대비'], ['taxSales', '영업 세금·보험율', 'pct', '착수금 대비'],\n      ['capRep', '영업 1명이 한 달에 소화하는 DB', 'num', '제후팀장 40~50개'], ['ramp1', '입사 첫 달 활동량', 'pct', ''], ['ramp2', '입사 둘째 달 활동량', 'pct', ''],\n      ['packs', 'DB 구매 (월, 1패키지=10개)', 'num', '발굴팀으로 대체하면 0'], ['packCost', 'DB 1패키지 비용', 'num', ''], ['taxRes', '세금 따로 떼어둘 비율', 'pct', '영업이익 대비. 제가 넣은 가정']]],\n    ['직원 · 고정비 · 개인지출', [['scoutSalary', '발굴팀 월급', 'num', ''], ['mgrFixed', '관리팀 1인 고정급', 'num', ''], ['mgrPct', '관리팀 수수료 인센티브율', 'pct', '성공수수료 매출 대비'],\n      ['mgrCap', '관리팀 1명이 처리하는 월 성공수수료', 'num', '넘으면 관리팀 1명 추가'], ['mgrOwnPct', '관리팀 별도계약 지급률', 'pct', '별도계약 매출의 몇 %를 지급'], ['scoutBonusDb', '발굴팀 추가지급 시작 DB 수', 'num', '이 개수 초과분부터'], ['scoutBonus', '발굴팀 DB 1개당 추가지급', 'num', ''], ['jobAd', '알바몬 공고비 (월)', 'num', ''], ['supplies', '집기 구매비 (월)', 'num', ''],\n      ['rentNow', '지금 월세', 'num', ''], ['card', '카드값', 'num', ''], ['home', '집값', 'num', ''], ['buffer', '항상 남겨둘 비상금', 'num', '제가 둔 가정']]],\n    ['사무실 이전', [['moveMonth', '이사하는 달', 'month', ''], ['depNow', '지금 보증금 (돌려받음)', 'num', ''], ['rentNew', '이사 후 월세', 'num', ''], ['depNew', '이사 후 보증금', 'num', ''], ['moveCost', '이사 · 세팅 비용', 'num', '']]],\n    ['대출 조건', [['L2rate', '햇살론 금리', 'pct', ''], ['L2sch', '햇살론 매달 원금', 'num', ''], ['L3rate', '신용취약 금리', 'pct', ''], ['L1rate', '재단 금리', 'pct', ''],\n      ['prStart', '원금 상환 시작 달', 'month', '재단 · 신용취약'], ['prMonths', '원금 상환 기간 (개월)', 'num', '제가 둔 가정'], ['payJaedan', '남는 돈으로 재단도 갚기', 'bool', '기본은 아니오'], ['giftRepay', '축의금으로 갚을 대출', 'num', '']]],\n    ['결혼', [['wedMonth', '결혼식 달', 'month', ''], ['wedFund', '결혼자금', 'num', ''], ['honey', '신혼여행 현지 소비', 'num', '제가 둔 가정'], ['gift', '축의금 예상', 'num', ''], ['hall', '엘리에나 잔금', 'num', ''],\n      ['houseTarget', '신혼집 보증금 총액', 'num', '3,000 또는 5,000'], ['eunDep', '은선님 보증금', 'num', '']]],\n    ['차 구입 (기본 제외)', [['carOn', '차 구입 포함', 'bool', ''], ['carPrice', '차 가격', 'num', ''], ['carSale', '현 차 매각', 'num', ''], ['carMonth', '구입하는 달', 'month', ''], ['carLoan', '차 대출', 'num', ''], ['carRate', '차 대출 금리', 'pct', ''], ['carTerm', '차 대출 기간 (개월)', 'num', '']]],\n    ['확장 (30명 규모)', [['expDep', '확장 사무실 보증금', 'num', ''], ['expSetup', '집기 · 세팅', 'num', ''], ['expBuf', '확장 직후 여유자금', 'num', '']]],\n    ['목표 기한', [['goalMonth', '목표 기한 (비우면 결혼 달)', 'month', '']]]\n  ];\n  const MOVED = [['L2', 'num'], ['L3', 'num'], ['L1', 'num'], ['customSave', 'num']];\n  const SCEN_FIELDS = [['cvr', '결제율', 'pct'], ['dbScout', '발굴팀 1명 월 DB', 'num'], ['ret', '신입 정착률', 'pct']];\n  const TOPK = [['periodEnd', 'month'], ['cash', 'num'], ['soFar', 'num'], ['finalC', 'num'], ['actualSave', 'num'], ['holdSave', 'num'], ['salesRev', 'num'], ['mgrSuccNow', 'num'], ['mgrOwnNow', 'num'], ['mgrOwnEnd', 'num']];\n  const NULLABLE = { finalC: 1, actualSave: 1, holdSave: 1, salesRev: 1, mgrSuccNow: 1, mgrOwnNow: 1, mgrOwnEnd: 1 };\n\n  function toDisp(t, v) { if (v == null || v === '') return ''; if (t === 'pct') return +(v * 100).toFixed(3); return v; }\n  function fromEl(t, el) {\n    const raw = el.value;\n    if (t === 'month') return raw;\n    if (raw === '') return null;\n    const n = parseFloat(raw); if (isNaN(n)) return undefined;\n    return t === 'pct' ? n / 100 : n;\n  }\n  let raf = 0;\n  function touch() { cancelAnimationFrame(raf); raf = requestAnimationFrame(() => { update(); Store.save(); }); }\n  function bindInput(el, key, t) {\n    el.value = toDisp(t, S.p[key]);\n    el.addEventListener('input', () => {\n      let v = fromEl(t, el); if (v === undefined) return;\n      if (v === null && !NULLABLE[key]) { if (t === 'month') v = ''; else return; }\n      if (t === 'month' && v === '' && key !== 'goalMonth') return;\n      S.p[key] = v; touch();\n    });\n  }\n  function syncInputs() {\n    TOPK.forEach(([k, t]) => { const el = $('in_' + k); el.value = toDisp(t, S.p[k]); });\n    $('in_goal').value = S.p.goal;\n    FIELDS.forEach(g => g[1].forEach(f => { const el = $('f_' + f[0]); if (el) el.value = f[2] === 'bool' ? String(S.p[f[0]] ? 1 : 0) : toDisp(f[2], S.p[f[0]]); }));\n    MOVED.forEach(([k, t]) => { const el = $('f_' + k); if (el) el.value = toDisp(t, S.p[k]); });\n    SCEN_FIELDS.forEach(f => [0, 1, 2].forEach(j => { $('s_' + f[0] + j).value = toDisp(f[2], S.p[f[0]][j]); }));\n    document.querySelectorAll('.chip').forEach(b => b.setAttribute('aria-pressed', String(+b.dataset.scen === S.p.scen)));\n    for (let k = 0; k < 3; k++) { $('db' + k).value = S.p.scoutDb[k] || ''; $('dbe' + k).value = S.p.scoutDbEnd[k] == null ? '' : S.p.scoutDbEnd[k]; }\n    HIRE_ROWS.forEach(h => { $('h_' + h.id).value = h.kind === 'sc' ? S.p.sc[h.idx] : S.p.sa[h.idx]; });\n  }\n\n  /* ---------- 가정 영역 만들기 ---------- */\n  function buildAssump() {\n    let h = '<h2>가정</h2><p class=\"hint\">처음 값은 지금까지 말씀해 주신 숫자입니다. 제가 임의로 둔 값은 설명에 표시했습니다.</p>';\n    h += '<details class=\"acc\" open><summary>시나리오별 숫자 (결제율 · 발굴 DB · 신입 정착률)</summary><div class=\"scen-grid\"><b></b><b>보수</b><b>기본</b><b>낙관</b>';\n    SCEN_FIELDS.forEach(f => { h += '<span>' + f[1] + '</span>'; [0, 1, 2].forEach(j => { h += '<input type=\"number\" step=\"any\" id=\"s_' + f[0] + j + '\" aria-label=\"' + f[1] + ' ' + ['보수', '기본', '낙관'][j] + '\">'; }); });\n    h += '</div><p class=\"hint\" style=\"margin-top:8px\">발굴 DB 160 = 하루 8개 × 20일. 제후팀장 결제율은 최근 약 30%입니다.</p></details>';\n    FIELDS.forEach(g => {\n      h += '<details class=\"acc\"><summary>' + g[0] + '</summary><div class=\"fgrid3\">';\n      g[1].forEach(f => {\n        h += '<label class=\"fld\"><span class=\"l\">' + f[1] + (f[2] === 'pct' ? ' <small>%</small>' : '') + '</span>';\n        if (f[2] === 'bool') h += '<select id=\"f_' + f[0] + '\"><option value=\"0\">아니오</option><option value=\"1\">예</option></select>';\n        else h += '<input id=\"f_' + f[0] + '\" type=\"' + (f[2] === 'month' ? 'month' : 'number') + '\" step=\"any\" inputmode=\"decimal\">';\n        if (f[3]) h += '<small>' + f[3] + '</small>';\n        h += '</label>';\n      });\n      h += '</div></details>';\n    });\n    h += '<div style=\"margin-top:14px\"><button class=\"btn quiet small\" type=\"button\" id=\"btnReset\">모든 값을 처음 상태로 되돌리기</button><div id=\"resetPanel\"></div></div>';\n    $('assump').innerHTML = h;\n    FIELDS.forEach(g => g[1].forEach(f => {\n      const el = $('f_' + f[0]);\n      if (f[2] === 'bool') el.addEventListener('change', () => { S.p[f[0]] = +el.value; touch(); });\n      else bindInput(el, f[0], f[2]);\n    }));\n    MOVED.forEach(([k, t]) => bindInput($('f_' + k), k, t));\n    SCEN_FIELDS.forEach(f => [0, 1, 2].forEach(j => {\n      const el = $('s_' + f[0] + j);\n      el.addEventListener('input', () => { const v = parseFloat(el.value); if (isNaN(v)) return; S.p[f[0]][j] = f[2] === 'pct' ? v / 100 : v; touch(); });\n    }));\n    $('btnReset').addEventListener('click', () => {\n      $('resetPanel').innerHTML = '<div class=\"confirm\"><b>저장된 값과 정산 기록이 모두 지워집니다.</b><div class=\"acts\"><button class=\"btn small\" type=\"button\" id=\"rsYes\">되돌리기</button><button class=\"btn quiet small\" type=\"button\" id=\"rsNo\">취소</button></div></div>';\n      $('rsNo').onclick = () => { $('resetPanel').innerHTML = ''; };\n      $('rsYes').onclick = () => { S = { v: 2, p: clone(E.DEFAULTS), log: [] }; S.p.periodEnd = autoPeriod(); $('resetPanel').innerHTML = ''; syncInputs(); touch(); };\n    });\n  }\n\n  /* ---------- 채용 영역 (입력칸은 한 번만 만든다) ---------- */\n  const HIRE_ROWS = [\n    { id: 'sc0', kind: 'sc', idx: 0, label: '발굴팀 #1' }, { id: 'sc1', kind: 'sc', idx: 1, label: '발굴팀 #2' }, { id: 'sc2', kind: 'sc', idx: 2, label: '발굴팀 #3' },\n    { id: 'sa0', kind: 'sa', idx: 0, label: '영업팀 #2' }, { id: 'sa1', kind: 'sa', idx: 1, label: '영업팀 #3' }\n  ];\n  function buildHire() {\n    $('hireInputs').innerHTML = HIRE_ROWS.map(r => '<label class=\"fld\"><span class=\"l\">' + r.label + '</span><input type=\"month\" id=\"h_' + r.id + '\" aria-label=\"' + r.label + ' 입사월\"></label>').join('');\n    let h = '<h2>직원은 언제 뽑으면 되나</h2><p class=\"hint\">입사월은 위 \"수정할 곳\"에서 바꿉니다. 공고는 입사 한 달 전에 올리는 것으로 봅니다.</p>';\n    h += '<div class=\"tbl-wrap\"><table><thead><tr><th>직원</th><th>입사월</th><th class=\"left\">필요한가</th><th>자금상 가장 빠른 달</th><th>공고 시작</th></tr></thead><tbody>';\n    HIRE_ROWS.forEach(r => { h += '<tr><td>' + r.label + '</td><td class=\"num\" id=\"hm_' + r.id + '\"></td><td class=\"left wrap-ok\" id=\"hj_' + r.id + '\"></td><td id=\"hs_' + r.id + '\"></td><td id=\"ha_' + r.id + '\"></td></tr>'; });\n    h += '<tr><td>관리팀 추가</td><td class=\"mutetxt\">자동</td><td class=\"left wrap-ok\" id=\"hj_mgr\"></td><td></td><td id=\"ha_mgr\"></td></tr>';\n    h += '</tbody></table></div><div id=\"hireNote\" style=\"margin-top:12px\"></div>';\n    $('hireBox').innerHTML = h;\n    HIRE_ROWS.forEach(r => {\n      const el = $('h_' + r.id);\n      el.addEventListener('input', () => { if (!el.value) return; if (r.kind === 'sc') S.p.sc[r.idx] = el.value; else S.p.sa[r.idx] = el.value; touch(); });\n    });\n  }\n  /* ---------- 계산 ---------- */\n  function autoPeriod() { const d = new Date(); return E.ymStr(d.getFullYear() * 12 + d.getMonth()); }\n  function compute() {\n    const p = S.p, P0 = E.ym(p.periodEnd), pj = p.goal === 'D' ? 1 : undefined;\n    const base = E.sim(p, { mode: 'plan', payJaedan: pj });\n    const cur = E.sim(p, { mode: 'plan', saveThis: p.actualSave, finalC: p.finalC, payJaedan: pj });\n    const S0 = cur.rows[0].free, Sh = p.holdSave != null ? p.holdSave : S0;\n    const hold = E.sim(p, { mode: 'hold', saveThis: S0, holdSave: Sh, finalC: p.finalC, payJaedan: pj });\n    const pp = Object.assign({}, p, { payJaedan: pj != null ? pj : p.payJaedan });\n    const o = { P0, base, cur, hold, S0, Sh,\n      mb: E.milestones(base, pp), mc: E.milestones(cur, pp), mh: E.milestones(hold, pp),\n      Sstar: E.solveS(p, null), Srest: E.solveS(p, S0),\n      okCur: E.goalOk(pp, cur), okHold: E.goalOk(pp, hold), okBase: E.goalOk(pp, base) };\n    o.staff = E.staffing(p, cur);\n    const baseO = { mode: 'plan', saveThis: p.actualSave, finalC: p.finalC, payJaedan: pj };\n    o.safe = {}; HIRE_ROWS.forEach(r => { o.safe[r.id] = E.safeStart(p, r.kind, r.idx, baseO); });\n    return o;\n  }\n  const dateOf = (res, idx) => idx < 0 ? null : res.rows[idx].label;\n  function deltaPill(a, b) {\n    if (a < 0 && b < 0) return '';\n    if (b < 0) return '<span class=\"pill bad\">기간 밖으로 밀림</span>';\n    if (a < 0) return '<span class=\"pill good\">앞당겨짐</span>';\n    const d = b - a;\n    if (d === 0) return '<span class=\"pill mute\">계획과 같음</span>';\n    return d > 0 ? '<span class=\"pill bad\">+' + d + '개월 늦음</span>' : '<span class=\"pill good\">' + (-d) + '개월 빠름</span>';\n  }\n  const dtxt = (res, idx) => idx < 0 ? '2028-12 이후' : res.rows[idx].label;\n\n  /* ---------- 화면 ---------- */\n  function renderHero() {\n    const p = S.p, r0 = R.cur.rows[0], b0 = R.base.rows[0];\n    const y0 = Math.floor(R.P0 / 12), m0 = R.P0 % 12, today = new Date(); today.setHours(0, 0, 0, 0);\n    const settle = new Date(y0, m0, 20), mend = new Date(y0, m0 + 1, 0);\n    const left = Math.round((settle - today) / 864e5), leftEnd = Math.round((mend - today) / 864e5);\n    $('sub').textContent = (m0 + 1) + '월 20일 정산 · ' + (m0 + 1) + '월 계약 기준 · ' + ((m0 + 1) % 12 + 1) + '월 지급분 · ' + (left >= 0 ? '정산일까지 D-' + left : '정산일 지남, 월말(계약 마감)까지 ' + Math.max(0, leftEnd) + '일');\n    if (p.settledMonth && p.settledMonth === p.periodEnd) $('sub').textContent += ' · 정산 완료 ✓';\n    const dIdx = E.goalIdx(p), dl = (dIdx >= 0 && dIdx < N) ? kr(R.P0 + dIdx) : '-';\n    const tile3Idx = R.mh.m3, tile3Base = R.mb.m3;\n    const diff = R.S0 - b0.free;\n    let h = '<div class=\"tiles\">';\n    h += '<div class=\"tile\"><div class=\"k\">' + (p.actualSave != null ? '이번 달 저축 (실제)' : '이번 달 예상 저축') + '</div><div class=\"v\">' + fmt(R.S0) + '<small>만원</small></div><div class=\"s\">계획 ' + fmt(b0.free) + ' · ' + (diff >= 0 ? '+' : '−') + fmt(Math.abs(diff)) + '</div></div>';\n    {\n      const A = settleFn('now'), cs = settleSolve(), more = Math.max(0, cs - A.sc), svv = p.customSave;\n      h += '<div class=\"tile\"><div class=\"k\">월 저축 ' + fmt(svv) + '을 지키려면</div><div class=\"v\">' + (more <= 0.05 ? '달성' : f1(more)) + '<small>' + (more <= 0.05 ? '' : '건 더') + '</small></div><div class=\"s\">' + (more <= 0.05 ? '지금까지 실적으로 충분합니다' : '착수금 약 ' + fmt(more * A.avg) + '만원 · 월말까지 총 ' + f1(cs) + '건') + '</div></div>';\n    }\n    h += '<div class=\"tile\"><div class=\"k\">신용취약 완납 · 이 속도 유지 시</div><div class=\"v\" style=\"font-size:26px\">' + dtxt(R.hold, tile3Idx) + '</div><div class=\"s\">계획 ' + dtxt(R.base, tile3Base) + ' ' + deltaPill(tile3Base, tile3Idx) + '</div></div>';\n    {\n      const mc = R.mc, low = mc.minCash, ok = low >= p.buffer - 1;\n      h += '<div class=\"tile\"><div class=\"k\">앞으로 가장 적은 현금</div><div class=\"v\" style=\"color:' + (ok ? 'var(--good)' : 'var(--bad)') + '\">' + fmt(low) + '<small>만원</small></div><div class=\"s\">' + R.cur.rows[mc.minIdx].label + ' · 비상금 ' + fmt(p.buffer) + ' ' + (ok ? '이상 유지' : '<span class=\"pill bad\">부족</span>') + '</div></div>';\n    }\n    h += '</div>';\n    const pc = Math.max(b0.contracts, 0.1), pct = Math.min(100, (p.soFar || 0) / pc * 100);\n    h += '<div><div class=\"row2\"><span>이번 달 계약 <b class=\"num\">' + f1(p.soFar || 0) + '</b> / 계획 <b class=\"num\">' + f1(b0.contracts) + '</b>건</span><span class=\"mutetxt\">' + Math.round(pct) + '%</span></div><div class=\"bar\" style=\"margin-top:6px\" role=\"progressbar\" aria-valuenow=\"' + Math.round(pct) + '\" aria-valuemin=\"0\" aria-valuemax=\"100\"><i style=\"width:' + pct + '%\"></i></div></div>';\n    // 판정 문장\n    const spd = fmt(R.Sh), sh = R.mh.m3;\n    const keep = sh >= 0 ? '이 속도(월 ' + spd + ')를 <b>' + (sh + 1) + '개월</b> 유지하면 ' + R.hold.rows[sh].label + '에 신용취약까지 갚습니다. 햇살론은 ' + dtxt(R.hold, R.mh.m2) + '입니다.' : '이 속도(월 ' + spd + ')로는 2028년 12월까지 신용취약을 다 갚지 못합니다.';\n    let tone, head, body;\n    if (p.goal === 'C') {\n      const ok = R.Sh >= p.customSave;\n      tone = ok ? 'good' : 'warn'; head = ok ? '월 저축 목표를 맞추고 있습니다.' : '월 저축이 목표보다 ' + fmt(p.customSave - R.Sh) + ' 모자랍니다.';\n      body = '목표 월 ' + fmt(p.customSave) + ' · 지금 ' + spd + '. ' + keep;\n    } else {\n      const gname = { A: '신용취약까지 완납', B: '햇살론 완납', D: '재단까지 전부 완납' }[p.goal];\n      if (R.okHold) { tone = 'good'; head = '이 속도로도 ' + dl + '까지 ' + gname + ' 목표를 맞출 수 있습니다.'; body = keep; }\n      else if (R.okCur) { tone = 'warn'; head = '계획대로 직원이 늘면 목표를 맞추지만, 지금 속도만으로는 어렵습니다.'; body = keep + ' 목표에는 월 <b>' + (R.Sstar == null ? '?' : fmt(R.Sstar)) + '</b> 이상이 필요합니다.'; }\n      else { tone = 'bad'; head = '이번 달 실적 기준으로는 ' + dl + '까지 ' + gname + ' 목표가 어렵습니다.'; body = '계획대로 가도 신용취약 완납은 ' + dtxt(R.cur, R.mc.m3) + '입니다. ' + keep + (R.Sstar == null ? '' : ' 기한을 지키려면 월 <b>' + fmt(R.Sstar) + '</b> 이상이 필요합니다.'); }\n    }\n    h += '<div class=\"verdict ' + tone + '\"><b>' + head + '</b><div class=\"t\" style=\"margin-top:4px\">' + body + '</div></div>';\n    $('hero').innerHTML = h;\n  }\n\n  /* ---------- 팀별 실적 → 월급 ---------- */\n  function team(mode, cOverride) {\n    const p = S.p, r0 = R.cur.rows[0], now = mode === 'now';\n    const sc = cOverride != null ? cOverride : (now ? (p.soFar || 0) : r0.contracts);\n    const avg = (p.soFar > 0 && p.salesRev != null) ? p.salesRev / p.soFar : p.fee;\n    const salesRev = cOverride != null ? cOverride * avg : (now ? (p.salesRev != null ? p.salesRev : sc * p.fee) : sc * avg);\n    const salesPay = salesRev * (p.incentive + p.taxSales);\n    const succ = now ? (p.mgrSuccNow != null ? p.mgrSuccNow : r0.succ) : Math.max(r0.succ, p.mgrSuccNow || 0);\n    const own = now ? (p.mgrOwnNow || 0) : (p.mgrOwnEnd != null ? p.mgrOwnEnd : (p.mgrOwnNow || 0));\n    const mgrPay = r0.mgrN * p.mgrFixed + p.mgrPct * succ + p.mgrOwnPct * own;\n    let scoutPay = 0, bonus = 0; const dbs = [];\n    for (let k = 0; k < r0.hcScout; k++) {\n      const db = now ? (p.scoutDb[k] || 0) : (p.scoutDbEnd[k] != null ? p.scoutDbEnd[k] : (p.scoutDb[k] || 0));\n      const b = Math.max(0, db - p.scoutBonusDb) * p.scoutBonus; dbs.push(db); bonus += b; scoutPay += p.scoutSalary + b;\n    }\n    return { sc, avg, salesRev, salesPay, succ, own, mgrPay, scoutPay, bonus, dbs, rev: salesRev + succ + own };\n  }\n  function settle(mode, cOverride) {\n    const p = S.p, r0 = R.cur.rows[0], t = team(mode, cOverride), sv = p.customSave, other = r0.cDb + r0.cAd + r0.cSup;\n    const op = t.rev - t.salesPay - t.mgrPay - t.scoutPay - other - r0.cRent, tax = Math.max(0, op) * p.taxRes;\n    const fixed = p.card + p.home + r0.cRent + r0.intTotal + r0.prin + r0.carP;\n    return Object.assign(t, { other, tax, sv, fixed, need: fixed + t.salesPay + t.mgrPay + t.scoutPay + other + tax + sv });\n  }\n  const settleFn = (m, c) => settle(m, c);\n  function settleSolve() {\n    const f = c => { const s = settle('end', c); return s.rev - s.need; };\n    if (f(0) >= 0) return 0; let lo = 0, hi = 300;\n    for (let k = 0; k < 60; k++) { const mid = (lo + hi) / 2; if (f(mid) >= 0) hi = mid; else lo = mid; }\n    return hi;\n  }\n  function renderTeams() {\n    const A = team('now'), B = team('end'), p = S.p;\n    $('tm_sales').innerHTML = '지금까지 <b class=\"num\">' + f1(A.sc) + '건 · 매출 ' + fmt(A.salesRev) + '</b> → 월급 <b class=\"num\">' + fmt(A.salesPay) + '</b> <span class=\"mutetxt\">(매출의 ' + Math.round((p.incentive + p.taxSales) * 1000) / 10 + '%)</span><br>월말 예상 ' + f1(B.sc) + '건 · 매출 ' + fmt(B.salesRev) + ' → 월급 ' + fmt(B.salesPay);\n    $('tm_mgr').innerHTML = '지금까지 수수료매출 ' + fmt(A.succ) + ' + 별도계약 ' + fmt(A.own) + ' → 월급 <b class=\"num\">' + fmt(A.mgrPay) + '</b> <span class=\"mutetxt\">(고정 ' + fmt(R.cur.rows[0].mgrN * p.mgrFixed) + ' + 수수료 ' + Math.round(p.mgrPct * 100) + '% + 별도계약 ' + Math.round(p.mgrOwnPct * 100) + '%)</span><br>월말 예상 월급 ' + fmt(B.mgrPay);\n    const h = R.cur.rows[0].hcScout;\n    $('tm_scout').innerHTML = h === 0 ? '이번 달 근무하는 발굴팀이 없습니다.' : '지금까지 월급 합계 <b class=\"num\">' + fmt(A.scoutPay) + '</b> (DB ' + A.dbs.map(x => fmt(x)).join(' / ') + '개, 추가지급 ' + fmt(A.bonus) + ')<br>월말 예상 월급 합계 ' + fmt(B.scoutPay) + ' (추가지급 ' + fmt(B.bonus) + ')';\n    for (let k = 0; k < 3; k++) { const on = k < h; $('scoutRow' + k).style.opacity = on ? 1 : .45; }\n  }\n\n  function renderSettle() {\n    const p = S.p, r0 = R.cur.rows[0], sv = p.customSave, nx = ((R.P0 + 1) % 12 + 1) + '월';\n    const A = settle('now'), B = settle('end');\n    const rows = [['카드값 (10일까지)', A.fixed && p.card, p.card], ['집 월세 (' + nx + ')', p.home, p.home], ['사무실 월세 (' + nx + ')', r0.cRent, r0.cRent],\n      ['영업팀 월급 (' + nx + ' 지급)', A.salesPay, B.salesPay], ['관리팀 월급', A.mgrPay, B.mgrPay], ['발굴팀 월급', A.scoutPay, B.scoutPay],\n      ['대출 이자 (' + nx + ')', r0.intTotal, r0.intTotal], ['대출 원금 (정해진 매달 상환분)', r0.prin + r0.carP, r0.prin + r0.carP],\n      ['공고·집기·DB비', A.other, B.other], ['세금 따로 떼어둘 돈', A.tax, B.tax], ['저축', sv, sv]];\n    let h = '<div class=\"row2\"><h2>20일 정산에 떼어 둘 돈</h2><span class=\"mutetxt\">단위 만원</span></div><p class=\"hint\">정산일에 ' + nx + '에 나갈 돈을 먼저 빼 두는 방식입니다. 위의 팀별 실적을 그대로 쓰고, 월말 예상은 아직 안 들어온 계약을 더한 값입니다.</p>';\n    h += '<div class=\"tbl-wrap\"><table><thead><tr><th></th><th>지금까지</th><th>월말 예상</th></tr></thead><tbody>';\n    rows.forEach(r => { h += '<tr><td>' + r[0] + '</td><td class=\"num\">' + fmt(r[1]) + '</td><td class=\"num\">' + fmt(r[2]) + '</td></tr>'; });\n    h += '<tr class=\"hl\"><td><b>떼어 둘 돈 합계</b></td><td class=\"num\"><b>' + fmt(A.need) + '</b></td><td class=\"num\"><b>' + fmt(B.need) + '</b></td></tr>';\n    h += '<tr><td>영업팀 착수금 매출</td><td class=\"num\">' + fmt(A.salesRev) + '</td><td class=\"num\">' + fmt(B.salesRev) + '</td></tr><tr><td>관리팀 수수료 매출</td><td class=\"num\">' + fmt(A.succ) + '</td><td class=\"num\">' + fmt(B.succ) + '</td></tr><tr><td>관리팀 별도계약 매출</td><td class=\"num\">' + fmt(A.own) + '</td><td class=\"num\">' + fmt(B.own) + '</td></tr>';\n    h += '<tr class=\"hl\"><td><b>들어오는 돈 합계</b></td><td class=\"num\"><b>' + fmt(A.rev) + '</b></td><td class=\"num\"><b>' + fmt(B.rev) + '</b></td></tr>';\n    const d = x => { const v = x.rev - x.need; return '<b class=\"num\" style=\"color:var(--' + (v >= -0.5 ? 'good' : 'bad') + ')\">' + (v >= -0.5 ? '+' : '−') + fmt(Math.abs(v)) + '</b>'; };\n    h += '<tr><td><b>여유(+) / 부족(−)</b></td><td>' + d(A) + '</td><td>' + d(B) + '</td></tr></tbody></table></div>';\n    const cs = settleSolve(), more = Math.max(0, cs - A.sc);\n    h += '<div class=\"verdict ' + (more <= 0.05 ? 'good' : (B.rev >= B.need ? 'warn' : 'bad')) + '\" style=\"margin-top:10px\"><b>' + (more <= 0.05 ? '지금까지 실적만으로 저축 ' + fmt(sv) + '까지 떼어 둘 수 있습니다.' : '저축 ' + fmt(sv) + '을 지키려면 영업 계약이 월말까지 ' + f1(cs) + '건이어야 하고, 지금보다 ' + f1(more) + '건(착수금 약 ' + fmt(more * A.avg) + ') 더 필요합니다.') + '</b><div class=\"t\" style=\"margin-top:4px\">' + (B.rev >= B.need ? '월말 예상대로면 저축 ' + fmt(sv) + '을 지키고도 ' + fmt(B.rev - B.need) + '이 남습니다.' : '월말 예상으로는 ' + fmt(B.need - B.rev) + ' 모자라 저축이 그만큼 줄어듭니다.') + ' 계약이 늘면 영업팀 월급도 같이 늘어나는 것까지 반영했습니다.</div></div>';\n    $('setBox').innerHTML = h;\n  }\n\n  function renderNeed() {\n    const p = S.p, r0 = R.cur.rows[0], cap = R.base.rows[0].contractsModel;\n    const lv = [['내 정산 기준', '20일에 떼는 항목 전부 + 저축 ' + fmt(p.customSave), p.customSave, () => { const c = settleSolve(), s = settle('end', c); return { contracts: c, fee: s.salesRev, rev: s.rev }; }], ['최소선', '이번 달 저축이 0이 되는 선', 0], ['계획대로', '원래 계획의 이번 달 저축', R.base.rows[0].free]];\n    if (R.Sstar != null) lv.push(['균등 목표', '지금부터 매달 같은 금액을 모아 목표를 맞출 때', R.Sstar]);\n    let h = '<div class=\"row2\"><h2>이번 달 매출은 얼마나 더 필요한가</h2><span class=\"mutetxt\">계약 1건 = 착수금 ' + fmt(p.fee) + '</span></div>';\n    h += '<p class=\"hint\">이번 달 성공수수료 <b class=\"num\">' + fmt(r0.succ) + '</b>은 2개월 전 계약에서 이미 정해져 있습니다. 이번 달에 움직일 수 있는 건 새 계약(착수금)뿐입니다.</p>';\n    h += '<div class=\"tbl-wrap\"><table><thead><tr><th>기준</th><th>이번 달 저축</th><th>필요 계약</th><th>필요 착수금</th><th>총 매출</th><th>지금까지</th><th>더 필요</th></tr></thead><tbody>';\n    lv.forEach(l => {\n      const n = l[3] ? l[3]() : E.needContracts(p, r0, l[2]), more = Math.max(0, n.contracts - (p.soFar || 0)), over = n.contracts > cap + 0.05;\n      h += '<tr><td title=\"' + esc(l[1]) + '\">' + l[0] + '<div class=\"mutetxt\" style=\"font-size:11px\">' + l[1] + '</div></td><td class=\"num\">' + fmt(l[2]) + '</td><td class=\"num\">' + f1(n.contracts) + '건</td><td class=\"num\">' + fmt(n.fee) + '</td><td class=\"num\">' + fmt(n.rev) + '</td><td class=\"num\">' + f1(p.soFar || 0) + '건</td><td>' +\n        (more <= 0.05 ? '<span class=\"pill good\">달성</span>' : '<b class=\"num\">' + f1(more) + '건</b> <span class=\"mutetxt\">(' + fmt(more * p.fee) + ')</span>' + (over ? ' <span class=\"pill bad\">이번 달 인력 한계 ' + f1(cap) + '건</span>' : '')) + '</td></tr>';\n    });\n    h += '</tbody></table></div>';\n    h += '<p class=\"hint\" style=\"margin-top:8px\">균등 목표는 직원이 아직 적은 초반에는 채우기 어렵습니다. 그럴 땐 \"계획대로\"를 따라가고, 12~3월에 직원이 자리 잡으며 만회하는 구조입니다.</p>';\n    $('needBox').innerHTML = h;\n  }\n\n  function renderSched() {\n    const p = S.p, cols = [['기준 계획', R.base, R.mb], ['이번 달 반영 · 계획대로', R.cur, R.mc], ['이 속도로 계속 유지', R.hold, R.mh]];\n    const rowsDef = [\n      ['햇살론 완납', m => dtxt(m.res, m.m2), m => deltaPill(R.mb.m2, m.m2)],\n      ['신용취약 완납', m => dtxt(m.res, m.m3), m => deltaPill(R.mb.m3, m.m3)],\n      ['결혼 달 말 현금', m => m.cashWed == null ? '-' : fmt(m.cashWed), m => (m.cashWed != null && m.cashWed < -0.5) ? '<span class=\"pill bad\">부족</span>' : ''],\n      ['확장 가능한 첫 달', m => dtxt(m.res, m.mExp), m => deltaPill(R.mb.mExp, m.mExp)]\n    ];\n    let h = '<h2>일정은 어떻게 바뀌나</h2><p class=\"hint\">오른쪽 열이 \"이번 달 저축 속도가 계속되면\"입니다.</p><div class=\"tbl-wrap\"><table><thead><tr><th></th>' + cols.map(c => '<th>' + c[0] + '</th>').join('') + '</tr></thead><tbody>';\n    rowsDef.forEach(rd => {\n      h += '<tr><td>' + rd[0] + '</td>';\n      cols.forEach(c => { const m = Object.assign({ res: c[1] }, c[2]); h += '<td><span class=\"num\">' + rd[1](m) + '</span> ' + (c[0] === '기준 계획' ? '' : rd[2](m)) + '</td>'; });\n      h += '</tr>';\n    });\n    h += '</tbody></table></div>';\n    $('schedBox').innerHTML = h;\n  }\n\n  function renderHire() {\n    const p = S.p, P0 = R.P0, st = R.staff, rows = R.cur.rows;\n    HIRE_ROWS.forEach(r => {\n      const start = E.ym(r.kind === 'sc' ? p.sc[r.idx] : p.sa[r.idx]), hired = start < P0, safe = R.safe[r.id];\n      let judge;\n      if (r.kind === 'sc') {\n        if (hired && r.idx === 0) judge = '<span class=\"pill good\">채용 완료</span>';\n        else if (r.idx + 1 <= st.needScouts) judge = '<span class=\"pill good\">필요</span> 영업이 소화할 DB를 채우려면 필요';\n        else judge = '<span class=\"pill warn\">없어도 됨</span> 발굴팀 ' + st.needScouts + '명이면 DB가 남습니다 (월 ' + fmt(rows[N - 1].gap) + '개 여유)';\n      } else judge = '<span class=\"pill good\">필요</span> 성과급이라 고정비 부담이 작음. 발굴팀이 DB를 쌓은 뒤 입사';\n      $('hj_' + r.id).innerHTML = judge;\n      $('hm_' + r.id).textContent = r.kind === 'sc' ? S.p.sc[r.idx] : S.p.sa[r.idx];\n      $('hs_' + r.id).innerHTML = (hired && r.idx === 0 && r.kind === 'sc') ? '-' : (safe == null ? '<span class=\"pill bad\">현금 부족</span>' : '<span class=\"num\">' + E.ymStr(safe) + '</span>');\n      let ad;\n      if (hired && r.kind === 'sc' && r.idx === 0) ad = '-';\n      else { const ok = safe != null && start >= safe; ad = '<span class=\"num\">' + E.ymStr(Math.max(start - 1, P0)) + '</span> ' + (ok ? '' : '<span class=\"pill bad\">현금 위험</span>'); }\n      $('ha_' + r.id).innerHTML = ad;\n    });\n    const mi = rows.findIndex(r => r.mgrN >= 2);\n    $('hj_mgr').innerHTML = mi >= 0 ? '<span class=\"pill warn\">' + rows[mi].label + '부터 필요</span> 성공수수료가 월 ' + fmt(p.mgrCap) + '을 넘어 관리팀 ' + rows[N - 1].mgrN + '명 필요' : '<span class=\"pill mute\">당분간 윤지팀장 1명</span>';\n    $('ha_mgr').innerHTML = mi >= 0 ? '<span class=\"num\">' + E.ymStr(Math.max(rows[mi].m - 1, P0)) + '</span>' : '-';\n    const last = rows[N - 1];\n    $('hireNote').innerHTML = '<div class=\"verdict ' + (st.nScoutPlan > st.needScouts ? 'warn' : 'good') + '\"><b>정상 상태에서 필요한 인원: 영업 ' + st.nSales + ' · 발굴 ' + st.needScouts + ' · 관리 ' + st.needMgr + '</b><div class=\"t\" style=\"margin-top:4px\">현재 계획은 영업 ' + st.nSales + ' · 발굴 ' + st.nScoutPlan + '입니다. 발굴팀이 한 달에 약 ' + fmt(st.scoutEff) + '개(정착률 반영)를 확보하고, 영업팀이 약 ' + fmt(st.capEff) + '개를 소화합니다. ' +\n      (st.nScoutPlan > st.needScouts ? '발굴팀을 ' + st.needScouts + '명으로 줄이면 월 ' + fmt(p.scoutSalary * (st.nScoutPlan - st.needScouts)) + '이 절약됩니다.' : '발굴과 영업 인원이 맞습니다.') + '</div></div>';\n  }\n\n  /* ---------- 차트 ---------- */\n  function niceStep(r) { const e = Math.pow(10, Math.floor(Math.log10(r / 4 || 1))), f = (r / 4) / e; return (f < 1.5 ? 1 : f < 3 ? 2 : f < 7 ? 5 : 10) * e; }\n  function chart(series, o) {\n    const W = 640, H = 240, pl = 52, pr = 14, pt = 30, pb = 28;\n    let lo = Math.min(0, ...series.flatMap(s => s.vals)), hi = Math.max(...series.flatMap(s => s.vals), o.line != null ? o.line : 0, 10);\n    const step = niceStep(hi - lo || 1); lo = Math.floor(lo / step) * step; hi = Math.ceil(hi / step) * step;\n    const X = i => pl + i / (N - 1) * (W - pl - pr), Y = v => pt + (1 - (v - lo) / (hi - lo)) * (H - pt - pb);\n    let s = '<svg class=\"chart\" viewBox=\"0 0 ' + W + ' ' + H + '\" role=\"img\" aria-label=\"' + esc(o.title) + '\">';\n    for (let v = lo; v <= hi + 1e-6; v += step) s += '<line class=\"grid\" x1=\"' + pl + '\" x2=\"' + (W - pr) + '\" y1=\"' + Y(v) + '\" y2=\"' + Y(v) + '\"/><text x=\"' + (pl - 6) + '\" y=\"' + (Y(v) + 4) + '\" text-anchor=\"end\">' + nf.format(v) + '</text>';\n    s += '<line class=\"axis\" x1=\"' + pl + '\" x2=\"' + (W - pr) + '\" y1=\"' + (H - pb) + '\" y2=\"' + (H - pb) + '\"/>';\n    for (let i = 0; i < N; i += 3) s += '<text x=\"' + X(i) + '\" y=\"' + (H - 8) + '\" text-anchor=\"middle\">' + R.cur.rows[i].label.slice(2) + '</text>';\n    (o.marks || []).forEach(m => { if (m.idx < 0 || m.idx >= N) return; const x = X(m.idx), tx = Math.min(W - pr - 22, Math.max(pl + 22, x)); s += '<line class=\"mk\" x1=\"' + x + '\" x2=\"' + x + '\" y1=\"' + (pt - 4) + '\" y2=\"' + (H - pb) + '\"/><text x=\"' + tx + '\" y=\"' + (pt - 10) + '\" text-anchor=\"middle\">' + m.t + '</text>'; });\n    if (o.line != null) s += '<line class=\"buf\" x1=\"' + pl + '\" x2=\"' + (W - pr) + '\" y1=\"' + Y(o.line) + '\" y2=\"' + Y(o.line) + '\"/><text x=\"' + (W - pr - 2) + '\" y=\"' + (Y(o.line) - 4) + '\" text-anchor=\"end\">비상금</text>';\n    series.forEach(sr => { s += '<path class=\"' + sr.cls + '\" d=\"' + sr.vals.map((v, i) => (i ? 'L' : 'M') + X(i).toFixed(1) + ' ' + Y(v).toFixed(1)).join(' ') + '\"/>'; });\n    return s + '</svg>';\n  }\n  function renderCharts() {\n    const p = S.p, wed = E.ym(p.wedMonth) - R.P0, mv = E.ym(p.moveMonth) - R.P0, pr = E.ym(p.prStart) - R.P0;\n    const marks = [{ idx: mv, t: '이사' }, { idx: wed, t: '결혼' }, { idx: pr, t: '원금상환' }];\n    const mk = (key) => [{ cls: 'ln-base', vals: R.base.rows.map(r => r[key]) }, { cls: 'ln-hold', vals: R.hold.rows.map(r => r[key]) }, { cls: 'ln-cur', vals: R.cur.rows.map(r => r[key]) }];\n    $('chartBox').innerHTML = '<h2>대출과 현금 추이</h2><div class=\"legend\"><span><i class=\"cur\"></i>이번 달 반영 · 계획대로</span><span><i class=\"hold\"></i>이 속도로 계속 유지</span><span><i class=\"base\"></i>기준 계획</span></div>' +\n      '<div class=\"charts\"><div><div class=\"mutetxt\">남은 대출 (만원)</div>' + chart(mk('debtTotal'), { title: '남은 대출 추이', marks }) + '</div><div><div class=\"mutetxt\">보유 현금 (만원)</div>' + chart(mk('cash'), { title: '보유 현금 추이', marks, line: p.buffer }) + '</div></div>';\n  }\n\n  function renderTable() {\n    const rows = R.cur.rows, p = S.p, ex = R.mc.mExp;\n    let h = '<div class=\"row2\"><h2>월별 계획 (이번 달 반영 · 계획대로)</h2><span class=\"mutetxt\">단위 만원</span></div><div class=\"tbl-wrap tbl-scroll\" style=\"margin-top:8px\"><table><thead><tr><th>월</th><th>인원</th><th>계약</th><th>총 매출</th><th>영업이익</th><th>월 저축</th><th>추가 상환</th><th>남은 대출</th><th>현금</th></tr></thead><tbody>';\n    rows.forEach(r => {\n      const tags = [r.eMove ? '이사' : '', r.eWed ? '결혼' : '', (r.m === E.ym(p.prStart)) ? '원금상환 시작' : '', (r.i === ex) ? '확장 가능' : ''].filter(Boolean).map(t => '<span class=\"pill mute\">' + t + '</span>').join(' ');\n      h += '<tr' + (r.i === 0 ? ' class=\"hl\"' : '') + '><td>' + r.label + ' ' + tags + '</td><td class=\"num\">' + (r.hcSales + r.hcScout + r.mgrN) + '</td><td class=\"num\">' + f1(r.contracts) + '</td><td class=\"num\">' + fmt(r.rev) + '</td><td class=\"num\">' + fmt(r.op) + '</td><td class=\"num\">' + fmt(r.free) + '</td><td class=\"num\">' + (r.pp1 + r.pp2 + r.pp3 > 0.5 ? fmt(r.pp1 + r.pp2 + r.pp3) : '-') + '</td><td class=\"num\">' + fmt(r.debtTotal) + '</td><td class=\"num\"' + (r.cash < p.buffer - 1 ? ' style=\"color:var(--bad);font-weight:600\"' : '') + '>' + fmt(r.cash) + '</td></tr>';\n    });\n    $('tblBox').innerHTML = h + '</tbody></table></div>';\n  }\n\n  /* ---------- 정산 마감 · 기록 ---------- */\n  function renderLog() {\n    const L = S.log; let cum = 0;\n    let h = '<div class=\"row2\"><h2>정산 기록</h2><span class=\"mutetxt\">마감할 때마다 한 줄씩 쌓입니다</span></div>';\n    if (!L.length) { $('logBox').innerHTML = h + '<p class=\"empty\">아직 기록이 없습니다. 정산일에 왼쪽의 \"이번 달 정산 마감\"을 누르면 이번 달 계약, 저축, 계획과의 차이가 여기에 남습니다.</p>'; return; }\n    h += '<div class=\"tbl-wrap\"><table><thead><tr><th>정산 월</th><th>계약</th><th>저축</th><th>계획 저축</th><th>차이</th><th>누적 차이</th><th>현금</th><th>남은 대출</th><th></th></tr></thead><tbody>';\n    L.forEach((e, i) => { const d = e.saving - e.plan; cum += d; h += '<tr><td>' + e.month + '</td><td class=\"num\">' + f1(e.contracts) + '</td><td class=\"num\">' + fmt(e.saving) + '</td><td class=\"num\">' + fmt(e.plan) + '</td><td class=\"num\" style=\"color:var(--' + (d >= 0 ? 'good' : 'bad') + ')\">' + (d >= 0 ? '+' : '') + fmt(d) + '</td><td class=\"num\" style=\"color:var(--' + (cum >= 0 ? 'good' : 'bad') + ')\">' + (cum >= 0 ? '+' : '') + fmt(cum) + '</td><td class=\"num\">' + fmt(e.cash) + '</td><td class=\"num\">' + fmt(e.debt) + '</td><td><button class=\"btn quiet small\" type=\"button\" data-del=\"' + i + '\">삭제</button></td></tr>'; });\n    $('logBox').innerHTML = h + '</tbody></table></div>';\n    $('logBox').querySelectorAll('[data-del]').forEach(b => b.onclick = () => { S.log.splice(+b.dataset.del, 1); renderLog(); Store.save(); });\n  }\n  function wireClose() {\n    $('btnClose').addEventListener('click', () => {\n      const r0 = R.cur.rows[0], b0 = R.base.rows[0], p = S.p;\n      const debtNow = (+p.L1 || 0) + (+p.L2 || 0) + (+p.L3 || 0);\n      $('closePanel').innerHTML = '<div class=\"confirm\"><b>' + kr(R.P0) + ' 20일 정산을 기록할까요?</b><div style=\"margin-top:6px;font-size:13px\">이번 달 저축 <b class=\"num\">' + fmt(r0.free) + '</b> (계획 ' + fmt(b0.free) + ')<br>보유 현금 <b class=\"num\">' + fmt(p.cash) + '</b> · 남은 대출 <b class=\"num\">' + fmt(debtNow) + '</b> (재단 ' + fmt(p.L1) + ' · 햇살론 ' + fmt(p.L2) + ' · 신용취약 ' + fmt(p.L3) + ')<br><span class=\"mutetxt\">위 현금과 대출 잔액이 정산을 마친 뒤 실제 금액인지 확인하세요. 기록하면 이 금액을 이미 저축·상환이 반영된 값으로 보고 계산합니다.</span></div><div class=\"acts\"><button class=\"btn small\" type=\"button\" id=\"clYes\">기록하기</button><button class=\"btn quiet small\" type=\"button\" id=\"clNo\">취소</button></div></div>';\n      $('clNo').onclick = () => { $('closePanel').innerHTML = ''; };\n      $('clYes').onclick = () => {\n        const entry = { month: p.periodEnd, saving: r0.free, plan: b0.free, contracts: r0.contracts, cash: p.cash, debt: debtNow, settledAt: new Date().toISOString() };\n        const k = S.log.findIndex(x => x.month === p.periodEnd);\n        if (k >= 0) S.log[k] = entry; else S.log.push(entry);\n        p.settledMonth = p.periodEnd;\n        $('closePanel').innerHTML = ''; update(); Store.save();\n      };\n    });\n  }\n\n  function renderFoot() {\n    $('foot').innerHTML = '<div>이 계획은 제 추정이 섞인 모델입니다. 성공수수료 건당 90, 결제율, 신입 정착률은 실제 실적으로 바꿀수록 정확해집니다.</div><div>대표님이 따로 받으시던 수수료 수입(월 500~1,000)은 넣지 않았습니다. 계속 들어온다면 모든 결과가 그만큼 좋아집니다.</div><div>세금과 비상금은 제가 임의로 둔 값이며 가정에서 바꿀 수 있습니다.</div>';\n  }\n\n  function update() {\n    try { R = compute(); } catch (e) { console.error(e); return; }\n    const hint = ({ 1: '결제율 20% · 신입 절반만 정착', 2: '결제율 25% · 신입 70% 정착', 3: '결제율 30% · 신입 90% 정착' })[S.p.scen];\n    $('scenHint').textContent = hint;\n    renderHero(); renderTeams(); renderSettle(); renderNeed(); renderSched(); renderHire(); renderCharts(); renderTable(); renderLog();\n  }\n\n  /* ---------- 시작 ---------- */\n  function wireCore() {\n    TOPK.forEach(([k, t]) => bindInput($('in_' + k), k, t));\n    for (let k = 0; k < 3; k++) {\n      $('db' + k).addEventListener('input', e => { const v = parseFloat(e.target.value); S.p.scoutDb[k] = isNaN(v) ? 0 : v; touch(); });\n      $('dbe' + k).addEventListener('input', e => { const v = parseFloat(e.target.value); S.p.scoutDbEnd[k] = isNaN(v) ? null : v; touch(); });\n    }\n    $('in_goal').addEventListener('change', () => { S.p.goal = $('in_goal').value; touch(); });\n    document.querySelectorAll('.chip').forEach(b => b.addEventListener('click', () => { S.p.scen = +b.dataset.scen; document.querySelectorAll('.chip').forEach(x => x.setAttribute('aria-pressed', String(x === b))); touch(); }));\n  }\n  function start(saved) {\n    if (saved && saved.p) { S.p = Object.assign(clone(E.DEFAULTS), saved.p); S.log = saved.log || []; }\n    else S.p.periodEnd = autoPeriod();\n    buildAssump(); buildHire(); wireCore(); wireClose(); renderFoot(); syncInputs(); update();\n    status(Store.ref ? '저장됨' : '저장됨', true);\n  }\n  wireCrm();\n  // 첫 화면은 바로 그리고, 저장된 값이 있으면 불러온 뒤 다시 그린다\n  buildAssump(); buildHire(); wireCore(); wireClose(); renderFoot(); S.p.periodEnd = autoPeriod(); syncInputs(); update();\n  Store.init().then(saved => { if (saved && saved.p) { S.p = Object.assign(clone(E.DEFAULTS), saved.p); S.log = saved.log || []; if (saved.v !== 2) { S.p.periodEnd = autoPeriod(); S.p.hist2 = E.DEFAULTS.hist2; S.p.hist1 = E.DEFAULTS.hist1; S.p.soFar = 0; } syncInputs(); update(); } status(Store.ref ? '저장됨' : '저장됨', true); })\n    .catch(() => status('저장됨', true)).then(() => syncCrm());\n})();\n\n</script>\n\n</body></html>\n"
